window.LX_DIAPOS = [{"id":"seance-1","numero":1,"titre":"المحاضرة الأولى: تقديم المقياس وتعريف الذكاء الاصطناعي","resume":"تعريف الذكاء الاصطناعي من خلال مهام قابلة للملاحظة، والحكم على شيء مألوف هل ينتمي إلى الذكاء الاصطناعي مع التعليل، ووصف ما تقيسه لعبة المحاكاة.","duree":"ساعة ونصف","lien":"cours.html#chapitre-1","fiche":"enseignant.html#guide-seance-1","diapos":[{"type":"titre","surtitre":"الذكاء الاصطناعي · الحصة 1","titre":"المحاضرة الأولى: تقديم المقياس وتعريف الذكاء الاصطناعي","sousTitre":"ماستر الأدب العام والمقارن · السداسي الثالث · جامعة يحيى فارس بالمدية · 2025–2026","notes":"ريثما يستقرّ الطلبة، اكتبوا على السبورة سؤالًا افتتاحيًا: «هل تستطيع آلة أن تقرأ رواية؟» لا تحسموه: فسيعود مع لعبة المحاكاة. وإن سمحت القاعة، فاعرضوا الصفحة الرئيسية للموقع، التي تحسب المشاعر في جملة ما: ماذا تعني «القراءة» بالنسبة إلى آلة؟ الوسائل التي ينبغي التحقق منها: جهاز العرض، والموقع مفتوحًا على بطاقة المقياس، والاستبيان المطبوع، وشرائط الورق."},{"type":"points","titre":"أهداف الحصة","points":["**تعريف** الذكاء الاصطناعي من خلال مهام قابلة للملاحظة","**الحكم** على شيء مألوف هل ينتمي إلى الذكاء الاصطناعي، مع التعليل","**وصف** لعبة المحاكاة وما تقيسه"],"notes":"اقرؤوا الأهداف الثلاثة بصوت مرتفع: يصف كلٌّ منها فعلًا إجرائيًا، وستتمكّنون في النهاية من التحقق من بلوغه. وأعلنوا سير الحصة: تقديم المقياس، ثم استبيان، ثم تصويت «ذكاء اصطناعي أم لا؟»، ثم عرض نظري، ثم لعبة يؤدي فيها طالبان دور الإنسان ودور الآلة."},{"type":"tableau","titre":"المقياس في سداسي واحد","entetes":["الجزء","المحتوى","المدة"],"lignes":[["الفصل 1","مدخل: تعريف الذكاء الاصطناعي، وتاريخه، وأنواع التعلم، والمقاربات","أسبوع واحد"],["الفصل 2","لغة Python: الأساسيات، وpandas وNumPy، والكائنات، والملفات النصية","أسبوعان"],["الفصل 3","الذكاء الاصطناعي الرمزي، والتعلم الآلي والعميق والمعزَّز","ستة أسابيع"],["المشروع المصغَّر","عمل شخصي مؤطَّر، يوزَّع في نهاية الفصل 2","ثلاثة أسابيع"],["الأعمال الموجَّهة والتطبيقية","تمارين مصحَّحة، ثم البرمجة بلغة Python","طوال السداسي"],["الموائد المستديرة","أربعة نقاشات: النشأة، ومناهج العلوم الإنسانية، والإشكاليات، والآفاق","نحو 45 دقيقة"]],"legende":"المدد محدَّدة في البرنامج الرسمي؛ أما الرزنامة الدقيقة فيحدّدها الأستاذ.","notes":"خصّصوا 15 دقيقة لهذه الشريحة والشريحة التالية. اعرضوا في الموقع بطاقة المقياس والرزنامة. واحسموا أمام الطلبة النقطتين اللتين يتركهما البرنامج مفتوحتين: توزيع التقييم، وفق النصوص المعمول بها في كليتكم، وعدد مواضيع المشروع المصغَّر («موضوع واحد يُختار» أو «3 مواضيع على الأقل من المواضيع الخمسة المقترحة»). وأعلنوا منذ اليوم القاعدة المعتمدة."},{"type":"points","titre":"كيف تعملون في هذا المقياس","points":["تبدأ البرمجة من **الصفر**: لا يُشترط أي مكتسب قبلي في الإعلام الآلي","نحو **ثلاث ساعات** من العمل الشخصي في الأسبوع، لكن بانتظام","**اختبروا أنفسكم** بدل إعادة القراءة، و**باعِدوا** بين المراجعات","اجتهدوا في كل تمرين من تمارين الأعمال الموجَّهة **قبل** فتح الحل","تعلّموا كل مصطلح **بالفرنسية** و**بالإنجليزية**"],"notes":"افتحوا صفحة «كيف تتعلّم هذا المقياس» واعرضوا جدول «أسبوع نموذجي»: خمس فترات، وثلاث ساعات في المجموع. وألحّوا على أن دراسة تركيبية لأبحاث علم نفس التعلّم (Dunlosky et al., 2013) تصنّف اختبار النفس والمباعدة بين المراجعات ضمن أكثر التقنيات فائدة؛ أما إعادة القراءة والتسطير فتمنحان انطباعًا بالتمكّن، لكن ما يبقى منهما في الذاكرة قليل. وطمئنوا الطلبة بشأن Python: سنبدأ من الصفر."},{"type":"activite","titre":"استبيان تشخيصي","duree":10,"consignes":["هل سبق لكم استعمال وكيل محادثة؟","هل سبق لكم أن كتبتم شيفرة؟","هل لديكم حاسوب محمول؟ واتصال بالإنترنت في البيت؟","بأي لغة تفضّلون قراءة التوثيق التقني؟","ماذا تنتظرون من هذا المقياس؟"],"materiel":"الاستبيان المطبوع، ورقة لكل طالب","notes":"المدة: 10 دقائق. اجمعوا الأوراق دون التعليق على الإجابات علنًا. ستُستعمل الإجابات المتعلقة بالتجهيزات في تكوين ثنائيات الأعمال التطبيقية: ضعوا كل طالب لا يملك حاسوبًا مع طالب مجهَّز. وستدلّكم لغة القراءة المفضّلة على من ينبغي توجيهه إلى النسخة الإنجليزية أو العربية من الموقع."},{"type":"activite","titre":"ذكاء اصطناعي أم لا؟ صوِّتوا","duree":15,"consignes":["صوِّتوا برفع الأيدي على كل شيء: ذكاء اصطناعي أم لا؟","الآلة الحاسبة · المدقق الإملائي · مرشّح الرسائل المزعجة · المترجم الآلي","منظّم الحرارة · محرك البحث · نظام GPS · وكيل المحادثة","حدِّدوا الأشياء التي يختلف حولها القسم","يعلّل متطوّع من كل فريق تصويته في جملة واحدة"],"notes":"المدة: 15 دقيقة. عُدّوا الأصوات ودوّنوا النتائج على السبورة، واحتفظوا بها إلى نهاية العرض النظري. لا تقدّموا أي إجابة: فالغرض هو إظهار الخلافات. الخلاصة التي ينبغي استخلاصها: إذا لم نتّفق، فذلك لأن علينا أولًا أن نعرّف ما نسمّيه «الذكاء الاصطناعي»."},{"type":"section","numero":1,"titre":"ما الذكاء الاصطناعي؟","sousTitre":"دارتموث، والوكلاء، وتعريف إجرائي","notes":"عرض نظري مدّته 20 دقيقة، انطلاقًا من درس «ما الذكاء الاصطناعي؟» في الفصل 1. وأعلنوا أنكم ستعودون بعد ذلك إلى الأشياء الثمانية التي صُوِّت عليها."},{"type":"chiffre","valeur":"1956","legende":"ورشة دارتموث: تصبح عبارة «الذكاء الاصطناعي» اسمًا لمجال بحثي","source":"مشروع حرّره سنة 1955 مكارثي ومينسكي وروتشستر وشانون","notes":"احكوا: في سنة 1955، طلب جون مكارثي ومارفن مينسكي وناثانيال روتشستر وكلود شانون تمويلًا لجمع باحثين في كلية دارتموث، بالولايات المتحدة، خلال صيف 1956. وكانت فرضيتهم أن كل جانب من جوانب التعلم والذكاء يمكن وصفه بدقة كافية تسمح لآلة بمحاكاته. وتُعدّ هذه الورشة شهادة ميلاد هذا المجال. وأضيفوا فورًا أنه لا يوجد تعريف واحد: فكلمة «الذكاء» نفسها ليست موضع إجماع."},{"type":"definition","terme":"الوكيل","traduction":"agent","definition":"نظام يدرك بيئته ويؤثّر فيها لبلوغ هدف ما.","exemple":"مرشّح الرسائل المزعجة «يدرك» نص الرسالة الإلكترونية و«يتصرّف» بوضعها في الصندوق المناسب.","notes":"هكذا يقدّم الكتاب المرجعي لستيوارت راسل وبيتر نورفيغ، *Artificial Intelligence: A Modern Approach* (1995)، الذكاءَ الاصطناعي: بوصفه دراسة الوكلاء. اطلبوا وكيلًا آخر من بين الأشياء الثمانية التي صُوِّت عليها. إجابات ممكنة: نظام GPS يدرك موقعًا ويقترح مسارًا؛ ومنظّم الحرارة يدرك درجة الحرارة ويؤثّر في التدفئة. ونبّهوا إلى أن هذا التعريف واسع جدًا: فهو لا يكفي للحسم."},{"type":"definition","terme":"الذكاء الاصطناعي","traduction":"intelligence artificielle (IA)","definition":"مجموعة الطرائق الحاسوبية التي تمكّن الآلة من إنجاز مهام نربطها عادةً بالذكاء البشري: التعرّف، والتصنيف، والتنبؤ، والاستدلال، والتخطيط، وفهم اللغة أو إنتاجها.","exemple":"التعرّف على حروف صحيفة قديمة (OCR)، والترجمة بين العربية والفرنسية، وفرز الرسائل الإلكترونية.","notes":"هذا هو التعريف الإجرائي للمقياس. أكّدوا أنه يتعلق بمهام قابلة للملاحظة، ولا يقول شيئًا عمّا «تفهمه» الآلة. وأضيفوا أن الحديث عن «الذكاء الاصطناعي» بصيغة المفرد مضلِّل: فهو عائلة من التقنيات (قواعد يكتبها الخبراء، واستكشاف الاحتمالات، والتعلم من الأمثلة، والشبكات العصبية). واطلبوا من الطلبة تدوين السؤال الذي ينبغي طرحه أمام كل نتيجة أنتجها «ذكاء اصطناعي»: أيّ تقنية، دُرِّبت على أيّ بيانات، ولأيّ مهمة؟"},{"type":"deux","titre":"لماذا يهمّ الذكاء الاصطناعي الدراساتِ الأدبية","colonnes":[{"titre":"روبرتو بوسا، 1949","points":["يسوعي إيطالي يفهرس أعمال توما الأكويني، بمساعدة شركة IBM","كثيرًا ما يُعدّ منشأ **الإنسانيات الرقمية** (*humanités numériques*)"]},{"titre":"فرانكو موريتي، 2000 و2013","points":["لا يستطيع أحد أن يقرأ كل الروايات المنشورة في القرن التاسع عشر","**القراءة عن بُعد** (*lecture distante*): آلاف النصوص، وسمات قابلة للقياس","وهي لا تحلّ محلّ القراءة عن قُرب"]}],"notes":"بالنسبة إلى الباحث المقارن، موريتي هو المرجع: «Conjectures on World Literature» (2000)، ثم *Distant Reading* (2013). ومن السمات القابلة للقياس: الأجناس الأدبية، والعناوين، وشبكات الشخصيات، وانتقال الأشكال من لغة إلى أخرى. واستعمالان ملموسان من الفصل 1: في سنة 2019، قدّم فلوريان كافييرو وجان باتيست كان حججًا كمّية لصالح موليير في الجدل الذي وضعه في مواجهة كورناي؛ ويمكن أيضًا مطابقة رواية لنجيب محفوظ مع ترجمتيها الفرنسية والإنجليزية جملةً بجملة لمقارنة اختيارات المترجمين."},{"type":"deux","titre":"العودة إلى الأشياء الثمانية","colonnes":[{"titre":"أمثلة يعتمدها المقياس","points":["مرشّح الرسائل المزعجة: وكيل يفرز الرسائل الإلكترونية","المترجم الآلي: ذكاء اصطناعي ضيّق","محرك البحث: الذكاء الاصطناعي في الحياة اليومية","نظام GPS: البحث عن مسار بين احتمالات عدة","وكيل المحادثة: نموذج لغوي كبير"]},{"titre":"للنقاش: أيّ تقنية؟","points":["الآلة الحاسبة: هل الحساب مهمة «ذكية»؟","منظّم الحرارة: يدرك ويتصرّف؛ فهل يكفي ذلك؟","المدقق الإملائي: قاموس، أم نموذج متعلَّم؟"]}],"notes":"عودوا إلى الأصوات المدوّنة على السبورة. واطرحوا بشأن كل شيء سؤال التعريف: هل ينجز مهمة نربطها بالذكاء البشري (التعرّف، والتصنيف، والتنبؤ، والتخطيط، وإنتاج اللغة)؟ الأشياء الخمسة الأولى أمثلة من الفصل 1؛ ويوضّح فيه حسابُ مسار بين المدية والجزائر العاصمة «البحث في فضاء الحالات». أما الثلاثة الأخرى، فاقبلوا فيها الإجابتين إذا عُلِّلتا بالتقنية المفترضة: فالتعليل هو المهم، لا الحكم."},{"type":"section","numero":2,"titre":"لعبة المحاكاة","sousTitre":"آلان تورينغ، 1950","notes":"المدة الإجمالية: 25 دقيقة، وهي النسخة المختصرة من نشاط الدليل: شاهدان، وخمس دقائق من الأسئلة، وتصويت، ونقاش."},{"type":"citation","texte":"أقترح أن ننظر في السؤال الآتي: هل تستطيع الآلات أن تفكّر؟","source":"آلان م. تورينغ، «Computing Machinery and Intelligence»، *Mind*، 1950","notes":"هذه هي الجملة الأولى من المقال، في ترجمة المقياس؛ أما الأصل فيقول: «I propose to consider the question, “Can machines think?”». اشرحوا ما فعله تورينغ: بدلًا من تعريف «التفكير»، يقترح اختبارًا قابلًا للملاحظة. في لعبته الأصلية، على المستجوِب أن يخمّن كتابيًا من الرجل ومن المرأة؛ ثم تأخذ آلةٌ أحد المكانين. فإذا لم يستطع تمييز الآلة من الإنسان، فإنها تتصرّف تصرّفًا ذكيًا: إنه «اختبار تورينغ»."},{"type":"activite","titre":"لنلعب: من الآلة؟","duree":25,"consignes":["شاهدان بعيدًا عن الأنظار: يجيب X بصدق، ويؤدي Y دور الآلة","يطرح القسم أسئلته كتابةً، على شرائط من الورق","خمس دقائق من الأسئلة لكل شاهد؛ ويقرأ الأستاذ الإجابات بصوت مرتفع","تصويت برفع الأيدي: من الآلة؟ ثم الكشف","نقاش: ما الذي فضح الآلة؟"],"materiel":"شرائط من الورق، ومكان بعيد عن الأنظار، وبطاقة القواعد التي تُسلَّم إلى Y","notes":"التوقيت: الأدوار 3 دقائق، والأسئلة 10 دقائق (خمس دقائق لكل شاهد، وهي المدة التي يذكرها تورينغ)، والتصويت 5 دقائق، والنقاش ما تبقّى. سلّموا Y خِفيةً بطاقة القواعد الواردة في الشريحة التالية، ولا تعرضوها إلا بعد التصويت. اقرؤوا أنتم كل الإجابات: فخطّ اليد قد يفضح الشاهدين. صيغة بديلة: يكون Y وكيل محادثة تقرؤون إجاباته؛ ويصبح السؤال عندئذ: «ماذا يُثبت نجاح الخداع؟»."},{"type":"points","titre":"الكشف: بطاقة قواعد «الآلة»","points":["يتضمّن السؤال «أنت» أو «أنتم»: «لماذا تطرح عليّ هذا السؤال؟»","يتضمّن كلمة تتعلّق بالعائلة: «حدّثني عن عائلتك.»","يطلب عملية حسابية: الانتظار ثلاثين ثانية، ثم الإجابة","في غير ذلك: «لست متأكدًا من أنني فهمت. هل يمكنك إعادة الصياغة؟»"],"notes":"لا تُعرض إلا بعد التصويت. هذه القواعد على نهج ELIZA، البرنامج الذي صمّمه جوزيف فايزنباوم (معهد MIT، 1966) والذي كان يحاكي معالجًا نفسيًا بإعادة صياغة جمل المستخدم. اسألوا: ما الذي فضح الآلة؟ هل عليها أن تحاكي أخطاءنا؟ في مثال تورينغ، تجيب الآلة عن عملية جمع بعد نحو ثلاثين ثانية، وتخطئ."},{"type":"question","titre":"نقاش","question":"هل خداع المستجوِب تفكير؟","reponse":"ليس بالضرورة: يستبدل تورينغ سؤالًا فلسفيًا باختبار قابل للملاحظة. والنجاح في الاختبار لا يُثبت الفهم.","explication":"هذا اعتراض الفيلسوف جون سيرل (1980)، بحجة الغرفة الصينية، التي سنراها في الحصة 2.","notes":"المدة: 10 دقائق من النقاش. دعوا الفريقين يعبّران قبل عرض الإجابة. النقطة التي ينبغي إبرازها: الاختبار يقيس سلوكًا، أي القدرة على التظاهر بأنه إنسان كتابةً؛ ولا يعرّف الذكاء ولا يُثبت الفهم."},{"type":"definition","terme":"أثر ELIZA","traduction":"effet ELIZA","definition":"الميل إلى نسبة الذكاء، بل الفهم الحقيقي، إلى برنامج يتكلّم.","exemple":"في سنة 1966، نسب بعض مستخدمي ELIZA إليه فهمًا حقيقيًا، مع أنه كان يكتفي بإعادة صياغة جملهم وفق قواعد بسيطة.","notes":"اربطوا ذلك باللعبة: إذا تردّد القسم أمام Y، الذي لم يكن يطبّق سوى أربع قواعد، فذلك هو أثر ELIZA. وهو يصدق أيضًا على وكلاء المحادثة الحاليين: الإجابة الجيدة لا تُثبت الفهم."},{"type":"points","titre":"أخطاء شائعة ينبغي تصحيحها","points":["اختزال الذكاء الاصطناعي في الروبوتات أو في وكلاء المحادثة الحديثة","الاعتقاد بأن النظام يفهم لأنه يجيب جيدًا: إنه **أثر ELIZA**","اعتبار اختبار تورينغ **تعريفًا** للذكاء"],"notes":"أعيدوا قراءة هذه الأخطاء الثلاثة واسألوا، بشأن كل منها، عمّا يسمح بتصحيحه في هذه الحصة. المنتظر: التعريف من خلال المهام وعائلة التقنيات (1)؛ وبطاقة قواعد «الآلة» (2)؛ وكون تورينغ يقترح اختبارًا قابلًا للملاحظة، لا تعريفًا (3)."},{"type":"fin","titre":"الحصيلة والعمل الشخصي","points":[{"texte":"**بطاقة الخروج** (5 دقائق)","sous":["شيء تعلّمتموه اليوم","سؤال ما زال قائمًا"]},{"texte":"**للقراءة** في الموقع","sous":["«ما الذكاء الاصطناعي؟» (الفصل 1)","«أسبوع نموذجي» (كيف تتعلّم هذا المقياس)"]},"**للتدوين**: استعمال للذكاء الاصطناعي صادفتموه هذا الأسبوع، مع التقنية المفترضة"],"texte":"الحصة 2: تاريخ الذكاء الاصطناعي، والذكاء الاصطناعي الضعيف والقوي","notes":"اجمعوا البطاقات واقرؤوها في المساء نفسه: فأفضل الأسئلة ستفتتح الحصة 2. وقبل إنهاء الحصة، تحقّقوا من بلوغ الأهداف بسؤالين سريعين: «عرِّفوا الذكاء الاصطناعي في جملة واحدة.» «ماذا تقيس لعبة المحاكاة؟»"}]},{"id":"seance-2","numero":2,"titre":"تاريخ الذكاء الاصطناعي، الذكاء الاصطناعي الضعيف والقوي","resume":"ترتيب نحو عشر محطات من تاريخ الذكاء الاصطناعي ووضع الشتاءين فيها، والتمييز بين الذكاء الاصطناعي الضيّق والعام، وبين الضعيف والقوي، وتلخيص حجة الغرفة الصينية في ثلاث جمل.","duree":"ساعة ونصف","lien":"cours.html#c1-histoire","fiche":"enseignant.html#guide-seance-2","diapos":[{"type":"titre","surtitre":"الذكاء الاصطناعي · الحصة 2","titre":"تاريخ الذكاء الاصطناعي، الذكاء الاصطناعي الضعيف والقوي","sousTitre":"الفصل 1 · لمحة تاريخية، الذكاء الاصطناعي الضيّق والعام، الغرفة الصينية","notes":"قبل الحصة: حضّروا بطاقة لكل محطة من التسلسل الزمني في الفصل 1 (الحدث على الوجه، والتاريخ على الظهر)، ومغناطيسات، وأقلام لبّاد بلونين. وارسموا على السبورة خطًا زمنيًا فارغًا، من 1940 إلى اليوم. وأعيدوا قراءة بطاقات الخروج من الحصة 1 لاختيار أسئلة التذكير الثلاثة."},{"type":"points","titre":"أهداف الحصة","points":["**ترتيب** نحو عشر محطات من تاريخ الذكاء الاصطناعي ووضع الشتاءين فيها","**التمييز** بين الذكاء الاصطناعي الضيّق والعام، وبين الضعيف والقوي","**تلخيص** حجة الغرفة الصينية في ثلاث جمل"],"notes":"أعلنوا سير الحصة: تذكير، ثم خط زمني يبنيه القسم، ثم زوجان من المفاهيم ينبغي عدم الخلط بينهما، ثم نقاش قصير حول الترجمة الآلية."},{"type":"points","titre":"تذكير: ثلاثة أسئلة من الذاكرة","progressif":true,"points":["في أي سنة، وأين، فرضت عبارة «الذكاء الاصطناعي» نفسها؟","من اقترح «لعبة المحاكاة»، وفي أي سنة؟","ماذا نسمّي «أثر ELIZA»؟"],"notes":"المدة: 5 دقائق. استبدلوا بهذه الأسئلة ثلاثة أسئلة مأخوذة من بطاقات الخروج للحصة 1 إن كانت لديكم أسئلة أفضل. يجيب الطلبة من الذاكرة، دون ملاحظات. الإجابات المنتظرة: سنة 1956، في ورشة دارتموث؛ آلان تورينغ، سنة 1950؛ الميل إلى نسبة فهم حقيقي إلى برنامج يتكلّم، كما فعل مستخدمو ELIZA (1966)."},{"type":"section","numero":1,"titre":"خط زمني جماعي","sousTitre":"من 1943 إلى اليوم: التأريخ، والوضع، والتلوين","notes":"المدة: 30 دقيقة، مع التصحيح. يعتمد التصحيح على شريحتَي التسلسل الزمني اللتين تليان النشاط."},{"type":"activite","titre":"تأريخ البطاقات ووضعها","duree":30,"consignes":["تتلقى كل مجموعة بضع بطاقات: الحدث على الوجه، والتاريخ على الظهر","أرِّخوا بطاقاتكم دون النظر إلى ظهرها","ضعوها على الخط الزمني المرسوم على السبورة","التصحيح: اقلبوا البطاقات وحرّكوا تلك التي وُضعت في غير مكانها","لوِّنوا: لون للمقاربة الرمزية، وآخر للمقاربة الاتصالية","حدِّدوا «شتاءَي الذكاء الاصطناعي»"],"materiel":"بطاقة لكل محطة من التسلسل الزمني في الفصل 1، ومغناطيسات، وأقلام لبّاد بلونين","notes":"وزّعوا البطاقات بحيث تحصل كل مجموعة على ثلاث أو أربع منها. أثناء الوضع، لا تصحّحوا: بل اطلبوا من كل مجموعة تعليل أحد تواريخها. وقبل التلوين، ذكّروا بالتيارين الفكريين: المقاربة الرمزية تبرمج قواعد واستدلالات صريحة؛ والمقاربة الاتصالية تجعل شبكات عصبية اصطناعية تتعلّم."},{"type":"chronologie","titre":"التصحيح: من الروّاد إلى الشتاء الأول","evenements":[{"date":"1943","texte":"ماكولوك وبيتس: العصبون الاصطناعي، سلف الشبكات العصبية"},{"date":"1950","texte":"يقترح تورينغ لعبة المحاكاة، التي ستُعرف بـ«اختبار تورينغ»"},{"date":"1956","texte":"ورشة دارتموث؛ وبرنامج Logic Theorist لنيويل وسايمون"},{"date":"1958","texte":"بيرسبترون روزنبلات؛ وتُبيَّن حدوده سنة 1969"},{"date":"1966","texte":"برنامج ELIZA (فايزنباوم، MIT) يحاكي معالجًا نفسيًا"},{"date":"1973","texte":"تقرير لايتهيل: شتاء الذكاء الاصطناعي الأول، إلى نحو سنة 1980"},{"date":"1970–1980","texte":"عصر الأنظمة الخبيرة، مثل MYCIN في جامعة ستانفورد"}],"notes":"صحّحوا بطاقةً بطاقة، مع السؤال عن لون كل واحدة. الاتصالية: 1943 و1958. الرمزية: برنامج Logic Theorist، الذي يبرهن مبرهنات في المنطق؛ وELIZA، الذي يعيد الصياغة وفق قواعد بسيطة؛ والأنظمة الخبيرة، التي تستدلّ ببضع مئات من القواعد من نوع «إذا… فإن…». لعبة المحاكاة اختبار، لا تقنية: فلا لون لها. وقد بيّن مينسكي وبابيرت حدود البيرسبترون في كتاب *Perceptrons* (1969). الشتاء الأول: تراجع التمويل، في المملكة المتحدة ثم في الولايات المتحدة."},{"type":"chronologie","titre":"التصحيح: من الشتاء الثاني إلى النماذج الكبيرة","evenements":[{"date":"1987","texte":"الشتاء الثاني: انهيار سوق آلات Lisp"},{"date":"1997","texte":"حاسوب Deep Blue (من IBM) يهزم غاري كاسباروف، بطل العالم في الشطرنج"},{"date":"2012","texte":"الشبكة AlexNet تتفوّق بوضوح على الطرائق الأخرى في مسابقة ImageNet"},{"date":"2016","texte":"برنامج AlphaGo (من DeepMind) يهزم لي سيدول في الغو، بأربعة انتصارات مقابل واحد"},{"date":"2017","texte":"مقال «Attention Is All You Need»: بنية المحوِّل (Transformer)"},{"date":"2022","texte":"في 30 نوفمبر، تتيح شركة OpenAI برنامج ChatGPT للجمهور"},{"date":"2024","texte":"اللائحة الأوروبية للذكاء الاصطناعي (AI Act): تصنيف الأنظمة بحسب مستوى الخطورة"}],"notes":"الشتاء الثاني: خيّبت الأنظمة الخبيرة الآمال، إذ كانت مكلفة الصيانة وهشّة خارج مجالها؛ فتراجعت الميزانيات حتى مطلع التسعينيات. الألوان: AlexNet والمحوِّل اتصاليان؛ ويجمع AlphaGo بين الشبكات العصبية والتعلم المعزَّز واستكشاف شجرة النقلات. فخّ: لم يكن Deep Blue يتعلّم، بل كان يستكشف بسرعة كبيرة ملايين الوضعيات. بطاقة 2018 إن كنتم قد أعددتموها: BERT (من Google)، وهو نموذج مسبق التدريب، وأول نموذج GPT من OpenAI."},{"type":"deux","titre":"تياران فكريان، ولونان","colonnes":[{"titre":"المقاربة الرمزية","points":["برمجة قواعد واستدلالات صريحة","برنامجا Logic Theorist (1956) وELIZA (1966)","السبعينيات والثمانينيات: الأنظمة الخبيرة"]},{"titre":"المقاربة الاتصالية","points":["جعل شبكات عصبية اصطناعية تتعلّم","العصبون الاصطناعي (1943)، والبيرسبترون (1958)","الشبكة AlexNet (2012)، والمحوِّل (2017)"]}],"notes":"اطلبوا من الطلبة نسخ هذا الجدول: فهو يلخّص الخط الزمني. واسألوا أين يوضع AlphaGo (2016). المنتظر: في الجانبين، لأنه يجمع بين الشبكات العصبية والبحث في شجرة النقلات؛ ونتحدث عندئذ عن مقاربة هجينة. أما Deep Blue فينتمي إلى البحث في فضاء الحالات."},{"type":"chiffre","valeur":"من 1958 إلى 1997","legende":"أعلن سايمون ونيويل أن حاسوبًا سيصبح بطل العالم في الشطرنج في غضون عشر سنوات. وقد استغرق ذلك قرابة أربعين سنة.","notes":"خصّصوا 10 دقائق لما يعلّمه التاريخ. اسألوا أولًا: كم من الوقت استغرق ذلك في الواقع؟ من تنبؤ هربرت سايمون وألن نيويل (1958) إلى فوز Deep Blue (1997)، قرابة أربعين سنة. وتصحب كلَّ موجة تقنية تنبؤاتٌ مفرطة في التفاؤل."},{"type":"points","titre":"دورات من الأمل والخيبة","points":[{"texte":"**شتاءان** في تاريخ الذكاء الاصطناعي","sous":["سنة 1973: تقرير لايتهيل، إلى نحو سنة 1980","سنة 1987: انهيار سوق آلات Lisp، حتى مطلع التسعينيات"]},{"texte":"الأفكار المهجورة تعود","sous":["الشبكات العصبية، التي عُدَّت بلا مستقبل سنة 1969","عادت سنة 1986 بفضل الانتشار العكسي، وهيمنت بعد 2012"]},"**درس منهجي**: احكموا على النظام بما يفعله، مقيسًا بالاختبارات، لا بما يُوعَد به"],"notes":"يعود الانتشار العكسي للتدرّج إلى ديفيد روملهارت وجيفري هينتون ورونالد ويليامز (1986). اطلبوا من الطلبة تطبيق الدرس المنهجي على وكيل محادثة حالي: كيف نحكم عليه؟ المنتظر: بالاختبارات، كأن نتحقق في فهرسٍ من المراجع التي يقترحها."},{"type":"section","numero":2,"titre":"زوجان من المفاهيم","sousTitre":"ذكاء اصطناعي ضيّق أم عام · ضعيف أم قوي","notes":"المدة: 20 دقيقة: التمييزان، والجدول المقارن، ثم الغرفة الصينية، تحكونها ثم يلخّصها الطلبة."},{"type":"deux","titre":"تمييزان ينبغي عدم الخلط بينهما","colonnes":[{"titre":"ضيّق أم عام: النطاق","points":["مهمة محدَّدة، أم كل المهام الفكرية البشرية؟","تمييز **تقني**"]},{"titre":"ضعيف أم قوي: العقل","points":["محاكاة الذكاء، أم امتلاك عقل حقًّا؟","تمييز **فلسفي** (جون سيرل، 1980)"]}],"notes":"يجمع البرنامج الرسمي بين الزوجين: «ذكاء اصطناعي ضيّق (أو ضعيف)» و«ذكاء اصطناعي عام (أو قوي)»، ويخلط الاستعمال الشائع بينهما. ألحّوا على أن السؤال الأول هو «ماذا يستطيع النظام أن يفعل؟»، والثاني «هل له عقل؟». مثال من الدرس: البرنامج الذي يهزم أبطال الشطرنج لا يعرف كيف يقرأ قصيدة؛ إنه ذكاء اصطناعي ضيّق."},{"type":"tableau","titre":"الذكاء الاصطناعي الضيّق والعام: مقارنة","entetes":["المعيار","الذكاء الاصطناعي الضيّق (الضعيف)","الذكاء الاصطناعي العام (القوي)"],"lignes":[["التعريف","مصمَّم ومدرَّب لمهمة محدَّدة","افتراضي، متعدد القدرات مثل الإنسان"],["أمثلة","حاسوب Deep Blue، وبرنامج AlphaGo، والترجمة الآلية","لا يوجد مثال حقيقي معترف به؛ وفي الخيال العلمي: HAL 9000"],["الوضع سنة 2026","حاضر في كل مكان: محركات البحث، والهواتف، والعلوم الإنسانية","هدف معلَن؛ ولا إجماع على أنه قد تحقّق"],["السؤال","هل النجاح في مهمة ما يعني فهمها؟","هل يمكن لآلة أن تفكّر، وأن تكون لها نوايا؟"]],"legende":"انطلاقًا من الجدول المقارن في الفصل 1","notes":"اطلبوا قراءة الجدول سطرًا سطرًا، ثم أخفوه واطلبوا إعادة كتابته من الذاكرة: هذا بالضبط ما يُطلب في الامتحان وفي المائدة المستديرة. ما يُنتظَر من ذكاء اصطناعي عام: نقل معارفه من مجال إلى آخر، وتعلّم مهمة جديدة بعدد قليل جدًا من الأمثلة، وفهم ما يعالجه فهمًا حقيقيًا، بالمعنى الذي يقصده سيرل. أما HAL 9000 فهو حاسوب فيلم *2001: أوديسا الفضاء*."},{"type":"etapes","titre":"الغرفة الصينية (سيرل، 1980)","progressif":true,"etapes":[{"titre":"غرفة مغلقة","texte":"شخص يجهل الصينية، ومعه دليل مكتوب بلغته"},{"titre":"رسائل بالصينية","texte":"تُمرَّر إليه حروف صينية عبر فتحة"},{"titre":"الدليل","texte":"يدلّه على الحروف التي ينبغي أن يعيدها ردًّا عليها"},{"titre":"من الخارج","texte":"تبدو الغرفة وكأنها تجيب بالصينية إجابة تامة"},{"titre":"ومع ذلك","texte":"لا يفهم الشخص شيئًا: التركيب، دون الدلالة"}],"notes":"احكوا تجربة التفكير خطوةً خطوة؛ وهي مأخوذة من مقال «Minds, Brains, and Programs» (1980). خلاصة سيرل: البرنامج، على المنوال نفسه، يعالج الرموز وفق شكلها (التركيب) من غير أن ينفذ إلى معناها (الدلالة)؛ ومن ثمّ فإن النجاح في اختبار تورينغ لن يُثبت الفهم. واذكروا أيضًا ردّ معارضيه: النظام بأكمله هو الذي قد يفهم. ولا يزال النقاش مفتوحًا."},{"type":"question","titre":"دوركم","question":"لخّصوا حجة الغرفة الصينية في ثلاث جمل.","reponse":"شخص يجهل الصينية يجيب عن رسائل بالصينية بفضل دليل من القواعد. تبدو إجاباته من الخارج تامة، لكنه لا يفهم شيئًا. وكذلك البرنامج يعالج الرموز دون أن يدرك معناها: فالنجاح في اختبار تورينغ لا يُثبت الفهم.","explication":"ثلاث مراحل: الوضعية، ثم الملاحظة، ثم الخلاصة المتعلقة بالبرامج.","notes":"المدة: 5 دقائق في صمت، ثم اطلبوا قراءة ملخّصين أو ثلاثة قبل عرض الإجابة. تحقّقوا من أن الجملة الثالثة تعمّم على البرامج: فهي التي تجعل من الحكاية حجة."},{"type":"activite","titre":"نقاش: هل يفهم المترجم الآلي؟","duree":20,"consignes":["السؤال: «هل يفهم المترجم الآلي ما يترجمه؟»","فريقان معيَّنان: نعم أو لا","متحدثان لكل فريق","ثم أسئلة من القاعة"],"notes":"عيّنوا الفريقين بأنفسكم، دون مراعاة الآراء: فالدفاع عن موقف لا نتبنّاه يُلزمنا بالإصغاء إلى الآخر. أفكار من الدرس يمكن طرحها إذا فتر النقاش: الغرفة الصينية؛ والمترجمات الآلية التي ظلت زمنًا طويلًا تترجم جملة تركية محايدة بـ«هو طبيب» ولكن بـ«هي ممرضة»؛ وإميلي بندر وشريكاتها في التأليف (2021)، اللواتي يرين في النماذج اللغوية الكبيرة «ببغاوات عشوائية» تعيد تركيب أشكال متعلَّمة."},{"type":"deux","titre":"الخلاصة: سؤالان متمايزان","colonnes":[{"titre":"ما يُلاحَظ","points":["هل الترجمة صحيحة؟","يمكن التحقق منها: نقارن ونختبر","سؤال الذكاء الاصطناعي **الضيّق**: مهمة محدَّدة"]},{"titre":"ما هو فلسفي","points":["هل ثمة فهم؟","النتيجة وحدها لا تكفي للحكم: الغرفة الصينية","سؤال الذكاء الاصطناعي **الضعيف أو القوي**: النقاش ما زال مفتوحًا"]}],"notes":"اختموا دون إعلان فائز، بالفصل بين السؤالين. ووسّعوا النقاش إلى النماذج اللغوية الكبيرة: فهي تحرّر النصوص وتلخّصها وتترجمها في كل المواضيع تقريبًا، لكنها دُرِّبت أولًا على التنبؤ بتتمّة متوالية من الكلمات، وترتكب أخطاء لا يرتكبها الإنسان. ولا يوجد إجماع يجعل منها ذكاءً اصطناعيًا عامًا: إنها أدوات قوية لكنها متخصصة، يجب التحقق من كل ما تنتجه."},{"type":"points","titre":"أخطاء شائعة ينبغي تصحيحها","points":["«الذكاء الاصطناعي الضعيف» لا يعني «قليل الأداء»: لقد هزم Deep Blue بطل العالم","لم يكن Deep Blue يتعلّم: بل كان يستكشف ملايين الوضعيات","النماذج اللغوية الكبيرة ليست ذكاءً اصطناعيًا عامًا"],"notes":"بالنسبة إلى كل خطأ، اطلبوا من طالب تصحيحه بعنصر من الخط الزمني أو من الجدول. فكلمة «ضعيف» تقابل «قوي»، أي مسألة العقل، لا «عالي الأداء». وبالنسبة إلى النماذج اللغوية: لا يوجد إجماع علمي على أن ذكاءً اصطناعيًا عامًا قد تحقّق."},{"type":"fin","titre":"الحصيلة والعمل الشخصي","points":["**الحصيلة** (5 دقائق): اكتبوا ثلاثة تواريخ تحتفظون بها، ولماذا",{"texte":"**العمل الشخصي**","sous":["إنجاز خط زمني شخصي من عشرة تواريخ","للمجموعة المعنية: تحضير المائدة المستديرة «نشأة الذكاء الاصطناعي وظهوره»"]}],"texte":"الحصة 3: أعمال موجَّهة، بإشراف أم دون إشراف؟","notes":"اجمعوا التواريخ الثلاثة: إذا غاب تاريخ أساسي كثيرًا، فعودوا إليه في بداية الحصة الموالية. طريقة الخط الزمني موصوفة في «كيف تتناول كل جزء»: عشرة تواريخ تكفي. وتذكّروا المكتسب القبلي للحصة 3: اطلبوا قراءة درس «التعلم الخاضع للإشراف وغير الخاضع للإشراف» في الفصل 1."}]},{"id":"seance-3","numero":3,"titre":"الأعمال الموجَّهة للفصل 1: بإشراف أم دون إشراف؟","resume":"تصنيف 8 وضعيات على الأقل من 10 (خاضع للإشراف، غير خاضع للإشراف، معزَّز) مع التعليل بالوسوم، وشرح دور مجموعة الاختبار، وإعطاء مثالين في العلوم الإنسانية والاجتماعية.","duree":"ساعة ونصف","lien":"cours.html#td-ch1","fiche":"enseignant.html#guide-seance-3","diapos":[{"type":"titre","surtitre":"الذكاء الاصطناعي · الحصة 3 · أعمال موجَّهة","titre":"الأعمال الموجَّهة للفصل 1: بإشراف أم دون إشراف؟","sousTitre":"فرز وضعيات، ومقارنة، والبحث عن أمثلة","notes":"المكتسب القبلي: درس «التعلم الخاضع للإشراف وغير الخاضع للإشراف» في الفصل 1. حضّروا عشر بطاقات وضعيات لكل مجموعة (الجدول الوارد في دليل الأستاذ لهذه الحصة)، وافتحوا في الموقع نصوص تمارين الأعمال الموجَّهة للفصل 1. وكوّنوا مجموعات من ثلاثة أو أربعة طلبة، مع المزج بين المستويات والتجهيزات."},{"type":"points","titre":"أهداف الحصة","points":["**تصنيف** 8 وضعيات على الأقل من 10: خاضع للإشراف، أو غير خاضع للإشراف، أو معزَّز","**تعليل** كل اختيار بالوسوم","**شرح** دور مجموعة الاختبار","**إعطاء** مثالين على التعلم في العلوم الإنسانية"],"notes":"للهدف الأول معيار رقمي: 8 وضعيات من 10. أعلنوه، فسيكون مرجعًا للمجموعات أثناء الفرز."},{"type":"activite","titre":"فرز عشر بطاقات وضعيات","duree":25,"consignes":["ضمن مجموعات من ثلاثة أو أربعة طلبة","وزّعوا البطاقات العشر على ثلاث كومات: خاضع للإشراف، غير خاضع للإشراف، معزَّز","دوّنوا على كل بطاقة القرينة الحاسمة","ثم تدافع كل مجموعة عن بطاقة واحدة أمام القسم"],"materiel":"عشر بطاقات وضعيات لكل مجموعة","notes":"أثناء الفرز، تجوّلوا بين المجموعات واسألوا «ماذا جرّبتم؟» بدلًا من إعطاء الإجابة. بطاقتان منها فخّان (الغو ومرشّح الرسائل المزعجة): لا تنبّهوا إليهما. وللدفاع، اختاروا المتحدث بالقرعة: فعلى كل واحد أن يكون مستعدًا. ولا تعرضوا التصحيح إلا بعد مداخلات الدفاع."},{"type":"deux","titre":"التصحيح: ثماني بطاقات بلا فخ","colonnes":[{"titre":"خاضع للإشراف: الأمثلة تحمل الإجابة","points":["تأريخ قصيدة انطلاقًا من 600 قصيدة مؤرَّخة","تقدير سنة نظم قصيدة (انحدار)","تصنيف 3000 خطاب انطلاقًا من 500 خطاب مصنَّف","رصد التعليقات التي تحضّ على الكراهية انطلاقًا من 5000 مثال موسوم","تحديد لغة رسالة انطلاقًا من رسائل موسومة"]},{"titre":"غير خاضع للإشراف: مجموعات تحتاج إلى تأويل","points":["توزيع 200 رواية على عائلات أسلوبية","تجميع 2000 إجابة مفتوحة دون شبكة تصنيف","إبراز موضوعات 1000 مقال"]}],"notes":"بالنسبة إلى كل بطاقة، اطلبوا ذكر القرينة: الأمثلة المؤرَّخة أو المصنَّفة أو الموسومة تدلّ على تعلم خاضع للإشراف؛ وغياب أي شبكة، مع مجموعات أو موضوعات ينبغي اكتشافها، يدلّ على تعلم غير خاضع للإشراف. سنة النظم وسم عددي: إنها مسألة انحدار، لا تصنيف. وبالنسبة إلى الخطابات الـ3000، ذكّروا باختبار الدرس: كون الخطابات الجديدة بلا وسوم أمر طبيعي، إذ هذا بالضبط ما يجب على النموذج التنبؤ به."},{"type":"question","titre":"الفخ رقم 1","question":"«تعلّم لعبة الغو بالفوز في المباريات أو خسارتها»: ما نوع التعلم؟","choix":["تعلم خاضع للإشراف","تعلم غير خاضع للإشراف","تعلم معزَّز"],"reponse":"تعلم معزَّز","explication":"لا توجد أمثلة مصحَّحة: يلعب البرنامج، فيكون الفوز أو الخسارة مكافأةً له أو عقوبة.","notes":"إجابة خاطئة محتملة: «غير خاضع للإشراف»، لغياب الوسوم. بيّنوا الفرق: هنا يتعلّم البرنامج بالفعل وتلقّي المكافآت. وهكذا تعلّم AlphaGo Zero (DeepMind، 2017) لعبة الغو باللعب ضد نفسه. وسيُدرَس التعلم المعزَّز في الفصل 3."},{"type":"question","titre":"الفخ رقم 2","question":"يتعلّم مرشّح انطلاقًا من الرسائل الإلكترونية التي وسمها المستخدمون بـ«مزعجة». ما نوع التعلم؟","choix":["تعلم خاضع للإشراف","تعلم غير خاضع للإشراف","تعلم معزَّز"],"reponse":"تعلم خاضع للإشراف","explication":"نقرة المستخدم على «مزعجة» وسمٌ: فكل مثال يحمل الإجابة الصحيحة.","notes":"إجابات خاطئة محتملة: «غير خاضع للإشراف»، لأن أحدًا لم يوسم الرسائل عمدًا، أو «معزَّز»، لأن المرشّح يتحسّن مع الاستعمال. والحال أن كل رسالة موسومة تحمل الإجابة المنتظرة: إنها وسم بالضبط. وفرز الرسائل الإلكترونية إلى «مزعجة» و«غير مزعجة» هو المثال النموذجي للتصنيف الخاضع للإشراف."},{"type":"etapes","titre":"السؤال الحاسم","etapes":[{"titre":"هل تحمل الأمثلة الإجابة؟","texte":"السؤال الذي يُطرح لكل وضعية، على أمثلة التدريب"},{"titre":"نعم: خاضع للإشراف","texte":"تصنيف إذا كانت الإجابة فئة، وانحدار إذا كانت عددًا"},{"titre":"لا: غير خاضع للإشراف","texte":"تكوّن الخوارزمية مجموعات على الباحث أن يؤوّلها"},{"titre":"مكافآت: تعلم معزَّز","texte":"يتعلّم البرنامج بالفعل وتلقّي المكافآت أو العقوبات"}],"notes":"المدة: 10 دقائق من الإثراء الجماعي. اكتبوا السؤال على السبورة: «هل تحمل أمثلة التدريب الإجابة الصحيحة؟» فهو يحسم كل الحالات تقريبًا. انتبهوا: ننظر في الأمثلة التي تُستعمل في التدريب، لا في الحالات الجديدة، التي لا تحمل وسمًا أبدًا."},{"type":"definition","terme":"مجموعة الاختبار","traduction":"jeu de test","definition":"جزء البيانات الذي يُعزَل جانبًا لتقييم النموذج على أمثلة لم يرها قط.","exemple":"مثل امتحان مؤلَّف من أسئلة لم يرها الطالب قط.","notes":"قاعدة ينبغي تدوينها: لا يُقيَّم النموذج أبدًا على الأمثلة التي استُعملت في تدريبه. بل تُقسَم البيانات قسمين: مجموعة التدريب (jeu d'entraînement) تضبط النموذج؛ ومجموعة الاختبار، المعزولة جانبًا، تقيس أداءه في النهاية. والهدف هو التعميم: أي حسن معالجة حالات جديدة."},{"type":"definition","terme":"الإفراط في التعلم","traduction":"sur-apprentissage","definition":"عيب في نموذج يحفظ تفاصيل مجموعة التدريب فيسيء التعميم على بيانات جديدة.","exemple":"نتائج شبه مثالية في التدريب، ومتواضعة في الاختبار: مثل الطالب الذي حفظ الحلول دون أن يفهم الدرس.","notes":"إشارة الإنذار: فارق كبير بين نتيجة التدريب ونتيجة الاختبار. في مثال الدرس، يحفظ نموذج معقَّد أكثر من اللازم قصائد التدريب بتفاصيلها العرضية، بدلًا من أن يدرك ما يميّز كل حقبة."},{"type":"question","titre":"فخ آخر: «enfans»","question":"كل قصائدكم الرومانسية مأخوذة من طبعات قديمة تكتب «enfans» بدلًا من «enfants». ماذا يتعلّم النموذج؟","reponse":"إملاء الطبعة، بدلًا من أسلوب الحقبة.","explication":"يعتمد النموذج على كل ما يميّز الأمثلة، ولو كان تفصيلًا عرضيًا: فالنتيجة الجيدة لا تضمن أنه تعلّم ما نبحث عنه.","notes":"مثال مأخوذ من الدرس. اتركوا الطلبة يبحثون دقيقة واحدة قبل عرض الإجابة. نقطة ينبغي أن يتذكّرها طلبة الأدب: معرفة أصل كل نص في المدوّنة (الطبعة، والإملاء، والرقمنة) جزء من المنهج."},{"type":"section","numero":2,"titre":"تمارين الأعمال الموجَّهة","sousTitre":"التمارين 1 إلى 3 في الحصة، والتمرين 4 عملًا شخصيًا","notes":"نصوص التمارين موجودة في الموقع، ضمن الأعمال الموجَّهة للفصل 1. اطلبوا من الطلبة ألا يفتحوا «عرض الحل» قبل التصحيح الجماعي."},{"type":"activite","titre":"التمرينان 1 و2","duree":25,"consignes":["التمرين 1: لكلٍّ من التعلم الخاضع للإشراف وغير الخاضع للإشراف، تعريف، والبيانات، والمهام، وصعوبة واحدة","التمرين 2: جدول مقارن بين نوعَي التعلم، يُكتب من الذاكرة","فرديًا أولًا، ثم ضمن ثنائيات","تصحيح جماعي"],"notes":"فرديًا، ثم ضمن ثنائيات، ثم التصحيح. يُكتب جدول التمرين 2 دون ملاحظات: هذا بالضبط ما يُطلب في الامتحان. وإذا أنهى ثنائي العمل مبكرًا، فاسألوه أين يضع التعلم شبه الخاضع للإشراف والتعلم الذاتي الإشراف."},{"type":"deux","titre":"تصحيح التمرين 1","colonnes":[{"titre":"خاضع للإشراف","points":["البيانات: أمثلة مرفقة **بوسمها** (رسالة إلكترونية و«مزعجة»)","المهام: التصنيف، والانحدار","التقييم: المقارنة بوسوم مجموعة الاختبار","الصعوبة: التوسيم مكلف؛ والوسوم تعكس اختيارات القائمين عليه، وأحيانًا أحكامهم المسبقة"]},{"titre":"غير خاضع للإشراف","points":["البيانات: أمثلة **بلا وسوم**","المهام: العنقدة، واختزال الأبعاد، وكشف الحالات الشاذة، والنمذجة الموضوعاتية","التقييم: تماسك المجموعات، وفائدتها في التأويل","الصعوبة: تسمية المجموعات المتحصَّل عليها وتأويلها"]}],"notes":"أكملوا شفويًا بالحالات الوسيطة. يجمع التعلم شبه الخاضع للإشراف بين بضعة أمثلة موسومة وكثير من الأمثلة الخام. أما التعلم الذاتي الإشراف فيستخلص الوسم من البيانات نفسها، كأن نخفي الكلمة التالية في جملة: وبهذه الطريقة تُدرَّب النماذج اللغوية الكبيرة تدريبًا مسبقًا. ولا توجد في التعلم المعزَّز أمثلة مصحَّحة: يتلقى وكيلٌ مكافآت أو عقوبات، ويتعلّم الاستراتيجية التي تجعل مكافآته أكبر ما يمكن."},{"type":"tableau","titre":"تصحيح التمرين 2","entetes":["المعيار","خاضع للإشراف","غير خاضع للإشراف"],"lignes":[["البيانات","أمثلة مرفقة بوسومها","أمثلة فقط"],["السؤال المطروح","أي فئة؟ أي قيمة؟","أي مجموعات، وأي بنى؟"],["المهام النموذجية","التصنيف، الانحدار","العنقدة، اختزال الأبعاد، الموضوعات"],["الخوارزميات","أنواع الانحدار، k أقرب الجيران، الأشجار، الشبكات","خوارزمية k-المتوسطات، التصنيف الهرمي، ACP، LDA"],["التقييم","مباشر: وسوم مجموعة الاختبار","غير مباشر: تماسك المجموعات، القراءة البشرية"],["العمل البشري","التوسيم قبل التعلم","التأويل بعد التعلم"],["مثال من العلوم الإنسانية والاجتماعية","نسبة نص مجهول المؤلف إلى مؤلف معروف","تجميع روايات بحسب معجمها"]],"legende":"في التعلم الخاضع للإشراف نتعلّم إعادة إنتاج إجابات معروفة؛ وفي التعلم غير الخاضع للإشراف نبحث عن تنظيم لا نعرفه بعد.","notes":"اطلبوا المقارنة سطرًا سطرًا مع جداول الثنائيات. تفصيل سطر «الخوارزميات»: الانحدار الخطي واللوجستي، وk أقرب الجيران، وأشجار القرار، والشبكات العصبية؛ وفي التعلم غير الخاضع للإشراف، تحليل المكوِّنات الرئيسية (ACP) وLDA للنمذجة الموضوعاتية. وبالنسبة إلى التقييم: الدقة أو متوسط الخطأ من جهة، ومعامل silhouette من جهة أخرى. واطلبوا نسخ جملة الخلاصة."},{"type":"activite","titre":"التمرين 3: ستة أمثلة على التعلم","duree":15,"consignes":["ضمن ثنائيات، ابحثوا عن ستة أمثلة على التعلم","لكل مثال: نوع التعلم، والمهمة، والبيانات المستعملة","مثالان على الأقل من العلوم الإنسانية أو من الأدب"],"notes":"تحقّقوا خصوصًا من انسجام النوع مع البيانات: إذا كانت الوسوم ضرورية، فالتعلم خاضع للإشراف. وشجّعوا الأمثلة المأخوذة من الدرس: القصائد، والروايات المغاربية، والخطابات السياسية، والرسائل بالدارجة، والاستبيانات حول القراءة."},{"type":"tableau","titre":"تصحيح التمرين 3: إجابة ممكنة","entetes":["المثال","النوع","المهمة","البيانات"],"lignes":[["فرز الرسائل الإلكترونية إلى «مزعجة» و«غير مزعجة»","خاضع للإشراف","التصنيف","رسائل وسمها المستخدمون"],["نسبة نص متنازَع عليه إلى مؤلف (القياس الأسلوبي)","خاضع للإشراف","التصنيف","نصوص معروفة المؤلف"],["تقدير تاريخ نظم قصيدة","خاضع للإشراف","الانحدار","قصائد معروفة التاريخ"],["تجميع روايات بحسب معجمها","غير خاضع للإشراف","العنقدة","نصوص فقط"],["أنماط المستجوَبين في استبيان حول القراءة","غير خاضع للإشراف","العنقدة","إجابات بلا وسوم"],["تعلّم لعبة الغو باللعب ضد النفس","معزَّز","أفعال متتالية","الأشواط الملعوبة؛ والفوز مكافأة"]],"legende":"إجابات أخرى ممكنة: تحقّقوا من انسجام النوع مع البيانات.","notes":"الأمثلة من العلوم الإنسانية والاجتماعية: القياس الأسلوبي، الذي طبّقه Mosteller وWallace سنة 1964 على بعض مقالات *Federalist Papers*؛ وتاريخ القصيدة؛ وأنماط القرّاء. أما الغو فيحيل إلى AlphaGo Zero (DeepMind، 2017). اطلبوا قراءة مثال واحد من كل ثنائي: ويقول القسم هل يتوافق النوع مع البيانات."},{"type":"activite","titre":"إطلاق التمرين 4","duree":15,"consignes":["هل تستطيع الحواسيب الحالية إنجاز هذه المهام الست؟ مهمة لكل ثنائي","لعب كرة الطاولة بشكل صحيح · قيادة سيارة في وسط مدينة · اكتشاف مبرهنات والبرهنة عليها","كتابة قصة مضحكة · إبداء رأي قانوني وجيه · إجراء عملية جراحية معقَّدة","حدِّدوا معيار النجاح: بالمقارنة مع مَن، وفي أي ظروف؟","ابحثوا عن مصادر أولية ومؤرَّخة","عرض مدّته 3 دقائق في الحصة الموالية"],"notes":"وزّعوا المهام الست، ولو اقتضى ذلك إسناد المهمة نفسها إلى عدة ثنائيات. ألحّوا على كلمات التعليمة: «بشكل صحيح»، و«وجيه»، و«مضحكة»؛ فتحديد هذه المعايير جزء من العمل. لا تعرضوا حل الموقع: فهو حالة المعارف في سبتمبر 2026، في مجال يتطوّر بسرعة كبيرة. وسيكون على الطلبة التحقق مما تغيّر منذ ذلك الحين."},{"type":"etapes","titre":"المنهجية: كيف تُجرون البحث","progressif":true,"etapes":[{"titre":"تحديد المعيار","texte":"بالمقارنة مع مبتدئ، أم محترف، أم أفضل البشر؟ وفي أي ظروف؟"},{"titre":"العودة إلى المصادر الأولية","texte":"مقالات محكَّمة، وتقارير تقنية؛ والنسخ الأولية (arXiv، HAL) بحذر"},{"titre":"عرض تجريبي، أم منتَج، أم إعلان؟","texte":"الشركة التي تقدّم منتَجها الخاص مصدرٌ صاحب مصلحة"},{"titre":"فحص الظروف","texte":"عدد المحاولات، والبيئة، والخصوم، ونصيب الإشراف البشري، ونسبة الإخفاق"},{"titre":"التأريخ والمقاطعة بين المصادر","texte":"تاريخ النتيجة، وتاريخ الاطلاع؛ ومصدران مستقلان على الأقل"},{"titre":"حكم دقيق","texte":"«نعم، ولكن…»، «في ظروف متحكَّم فيها»، «ليس بعد»"}],"notes":"تصلح هذه المنهجية لكل بحث وثائقي حول الذكاء الاصطناعي. النسخ الأولية السابقة للنشر مفيدة، لكنها لم تخضع دائمًا لتحكيم الأقران؛ ويساعد Google Scholar على العثور على المقالات. وللمقاطعة بين المصادر، يمكن أن يُستعمل مؤلَّف تركيبي، مثل كتاب جان غابرييل غاناسيا (*L'IA expliquée aux humains*، 2024) المذكور في مراجع المقياس، مصدرًا ثانيًا. فالفروق الدقيقة هي الإجابة المنتظرة، وليست اعترافًا بالضعف."},{"type":"points","titre":"أخطاء شائعة ينبغي تصحيحها","points":["«غير خاضع للإشراف» لا يعني «دون إنسان»: فالباحث يختار، ثم يؤوّل","الحالات الجديدة لا تحمل وسمًا: وليس هذا سببًا للحكم بأن التعلم غير خاضع للإشراف","**التصنيف**: فئات معروفة؛ **العنقدة**: مجموعات مكتشَفة"],"notes":"اطلبوا، بشأن كل خطأ، البطاقةَ التي تكشفه. الخطأ الأول: يختار الباحث البيانات وعدد المجموعات، ثم يؤوّل النتائج؛ فالروايات الـ200 لا تنتظم وحدها في «عائلات». الثاني: الخطابات الـ3000. الثالث: تأريخ قصيدة انطلاقًا من 600 قصيدة مؤرَّخة (تصنيف) مقابل توزيع 200 رواية على عائلات أسلوبية (عنقدة)."},{"type":"fin","titre":"العمل الشخصي","points":[{"texte":"**تحضير التمرين 4**: عرض مدّته 3 دقائق","sous":["يعود حل الموقع إلى سبتمبر 2026: تحقّقوا مما تغيّر منذ ذلك الحين"]},"**إعادة قراءة** «مقاربات الذكاء الاصطناعي» (الفصل 1)","**حفظ** مسرد المصطلحات، بالفرنسية والإنجليزية"],"texte":"الحصة القادمة: أول حصة أعمال تطبيقية بلغة Python","notes":"قبل إنهاء الحصة، تحقّقوا من الهدف الرقمي بتصويت برفع الأيدي: من صنّف 8 بطاقات على الأقل من 10؟ يُحفَظ المسرد أزواجًا: بطاقة من الفرنسية إلى الإنجليزية، وبطاقة من الإنجليزية إلى الفرنسية، مع التعريف على الظهر."}]},{"id":"seance-4","numero":4,"titre":"أول أعمال تطبيقية بلغة Python: متغيّرات وقوائم وكلمات قصيدة","resume":"فتح دفتر تفاعلي، وإنشاء متغيّرات وقائمة، ثم عدّ كلمات مقطع شعري لفيرلين وتفسير الفارق الناتج عن علامات الترقيم.","duree":"ساعة ونصف","lien":"cours.html#c2-fondamentaux","fiche":"enseignant.html#guide-seance-4","diapos":[{"type":"titre","surtitre":"الفصل 2 · الحصة 4 · أعمال تطبيقية (TP)","titre":"أول أعمال تطبيقية بلغة Python","sousTitre":"دفتر تفاعلي، ومتغيّرات، وقائمة، وكلمات قصيدة لفيرلين","notes":"قبل الحصة: تحقّقوا من أن حسابات Google قد أُنشئت (من أجل Colab) أو من أن Jupyter يُفتح، مثلًا بواسطة `run.bat notebook`. حضّروا دفترًا تفاعليًا يتضمّن عناوين المراحل، وكبّروا الخط: فستكتبون الشيفرة مباشرةً أمام الطلبة. يكفي حاسوب لكل طالبين؛ ولا تُشترط أي مكتسبات قبلية في البرمجة."},{"type":"points","titre":"أهداف الحصة","points":["فتح **دفتر تفاعلي**، وتنفيذ خلية وحفظها","إنشاء **متغيّرات** و**قائمة**","عدّ كلمات مقطع شعري لفيرلين","تفسير الفارق بين «العناصر» و«الكلمات»: علامات الترقيم"],"notes":"اقرؤوا الأهداف بصوت مرتفع وطمئنوا الطلبة: لا يُفترض في أحد أن يعرف البرمجة مسبقًا. أعلنوا قاعدة اليوم: نتوقّع المُخرَج قبل التنفيذ، ونقرأ رسائل الخطأ بدل أن نخشاها. وفي نهاية الحصة، ينبغي أن يستطيع كل طالب أن يقول ما تفعله `split()` وما يعنيه `NameError`."},{"type":"activite","titre":"تكوين الثنائيات","duree":10,"consignes":["حاسوب لكل طالبين: **القائد** يمسك لوحة المفاتيح، و**المساعد** يقرأ نص التمرين ويراجع ويقترح","يبدأ الأقل تمكّنًا بلوحة المفاتيح؛ ولا يأخذها منه المساعد أبدًا","يتبادلان الدورين كل 15 دقيقة، عند الإشارة","البيئة الافتراضية: Google Colab، داخل المتصفح"],"materiel":"حواسيب، واتصال بالإنترنت، وحسابات Google (من أجل Colab) أو Jupyter مثبَّت","notes":"كوّنوا الثنائيات بناءً على الاستبيان: امزجوا بين المستويات والتجهيزات، وضعوا الطلبة الذين لا يملكون حاسوبًا مع زميل مجهَّز. لا يتطلّب Colab تثبيت أي شيء: يكفي حساب Google. وأنتم من يعطي إشارة تبادل الدورين."},{"type":"section","numero":1,"titre":"أول دفتر تفاعلي","sousTitre":"خلية، وShift + Enter، ونتيجة","notes":"15 دقيقة. الهدف: أن يرى كل ثنائي أول نتيجة له تظهر على الشاشة."},{"type":"etapes","titre":"فتح دفتر تفاعلي واستعماله","progressif":true,"etapes":[{"titre":"فتح Colab","texte":"افتحوا colab.research.google.com، ثم أنشئوا دفترًا تفاعليًا"},{"titre":"كتابة الشيفرة","texte":"داخل خلية، دون نسخ ولصق"},{"titre":"التنفيذ","texte":"اضغطوا Shift + Enter: فتظهر النتيجة تحت الخلية"},{"titre":"الحفظ","texte":"في Google Drive: فملفات الجلسة تُمحى عند إغلاقها"}],"notes":"يمزج الدفتر التفاعلي خلايا الشيفرة ونتائجها والنص. ومع Jupyter، شغّلوا `run.bat notebook` أو اكتبوا `jupyter notebook` في الطرفية: فيُفتح تبويب في المتصفح. اعرضوا كل حركة على جهاز العرض، ثم تجوّلوا بين الصفوف حتى يرى كل طالب نتيجته."},{"type":"code","titre":"الخلية الأولى","code":"# Un commentaire : Python ignore cette ligne\nprint(\"Bonjour, Médéa !\")\nprint(\"Kateb Yacine est né en\", 1929)","sortie":"Bonjour, Médéa !\nKateb Yacine est né en 1929","legende":"تعرض `print()` القيم التي تُعطى لها، مفصولة بمسافة.","notes":"اكتبوا الشيفرة مباشرةً مع شرح ما تفعلونه، ثم اضغطوا Shift + Enter. نبّهوا إلى علامات التنصيص المستقيمة، والأقواس، والفاصلة التي تفصل النص عن العدد 1929. وما يلي الرمز # تعليق موجَّه إلى القارئ البشري."},{"type":"section","numero":2,"titre":"المتغيّرات والقوائم","sousTitre":"تخزين القيم تحت اسم","notes":"30 دقيقة: المتغيّرات والأنواع (15 دقيقة)، ثم القوائم (15 دقيقة)."},{"type":"definition","terme":"المتغيّر","traduction":"variable","definition":"اسمٌ يدلّ على قيمة في الذاكرة. والعلامة = تعني «يأخذ» لا «يساوي».","exemple":"التعليمة `annee = 1956` تخزّن 1956 تحت الاسم `annee`.","notes":"ألِحّوا على معنى العلامة =: «annee يأخذ 1956». ولكل قيمة نوع: int (عدد صحيح)، وfloat (عدد عشري)، وstr (سلسلة محارف، بين علامتي تنصيص)، وbool (True أو False). ولا يحتوي اسم المتغيّر على مسافات، ويُفضَّل ألّا يحتوي على حروف ذات علامات: نصل بين الكلمات بشرطة سفلية، مثل `mots_par_page`."},{"type":"code","titre":"المتغيّرات والأنواع وسلاسل f-string","code":"titre = \"Nedjma\"   # str : chaîne de caractères\nannee = 1956       # int : nombre entier\nprint(type(titre), type(annee))\nprint(f\"{titre} de Kateb Yacine paraît en {annee}.\")","sortie":"<class 'str'> <class 'int'>\nNedjma de Kateb Yacine paraît en 1956.","legende":"في سلسلة **f-string**، يُستبدل كلُّ تعبير بين قوسين معقوفين بقيمته.","notes":"اطلبوا توقّع كل سطر قبل التنفيذ. تعطي `type()` نوع القيمة: str للنص، وint للعدد الصحيح. سؤال يُطرح: ماذا يحدث إذا نسينا الحرف f قبل علامات التنصيص؟ المنتظر: تظهر الأقواس المعقوفة كما هي، `{titre}` بدل Nedjma."},{"type":"code","titre":"خطأ متعمَّد","code":"titre = \"Nedjma","sortie":"SyntaxError: unterminated string literal (detected at line 1)","legende":"السطر الأخير من الرسالة: نوع الخطأ، ثم شرحه (سلسلة غير منتهية).","notes":"انسوا عمدًا علامة التنصيص الختامية ونفّذوا. تبدأ الرسالة بموضع الخطأ، مع علامة ^ تحت الموضع المعيب؛ اقرؤوا أولًا السطر الأخير، بصوت مرتفع: «سلسلة محارف غير منتهية، اكتُشفت في السطر 1». صحّحوا، وأعيدوا التنفيذ. الرسالة التي ينبغي إيصالها: الخطأ معلومة، لا فشل."},{"type":"question","titre":"التوقّع قبل التنفيذ","question":"إذا كانت `auteurs = [\"Hugo\", \"Baudelaire\", \"Maupassant\"]`، فما قيمة `auteurs[0]`؟","choix":["Hugo","Baudelaire","Maupassant","خطأ"],"reponse":"القيمة Hugo: فالفهارس تبدأ من 0.","explication":"يدلّ `auteurs[0]` على العنصر الأول، و`auteurs[1]` على الثاني، و`auteurs[-1]` على الأخير.","notes":"اطلبوا التصويت برفع الأيدي قبل كشف الإجابة. سيجيب كثيرون Baudelaire: وهو الخطأ الشائع المتمثّل في البحث عن العنصر الأول عند `[1]`. ثم نفّذوا الشيفرة للحسم."},{"type":"code","titre":"القوائم","code":"auteurs = [\"Hugo\", \"Baudelaire\", \"Maupassant\"]\nauteurs.append(\"Kateb Yacine\")       # ajouter à la fin\nprint(auteurs[0], \"|\", auteurs[-1])  # premier et dernier\nprint(len(auteurs), \"auteurs\")\nauteurs.sort()                       # trier sur place\nprint(auteurs)\nprint(auteurs[1:3])                  # positions 1 et 2","sortie":"Hugo | Kateb Yacine\n4 auteurs\n['Baudelaire', 'Hugo', 'Kateb Yacine', 'Maupassant']\n['Hugo', 'Kateb Yacine']","legende":"تضيف `append` في النهاية، وتفرز `sort` القائمة في مكانها، وتعدّ `len` العناصر.","notes":"نفّذوا مع طلب توقّع كل سطر. يدلّ `auteurs[-1]` على العنصر الأخير. وتأخذ الشريحة `auteurs[1:3]` الموضعين 1 و2: فالحدّ الأيمن مستبعَد. وتعدّل `sort()` القائمة نفسها، بالترتيب الأبجدي."},{"type":"section","numero":3,"titre":"عدّ كلمات قصيدة","sousTitre":"قصيدة «Il pleure dans mon cœur» لفيرلين (1874)","notes":"25 دقيقة، منها وقت كتابة البرنامج."},{"type":"activite","titre":"عدّ كلمات مقطع شعري","duree":25,"consignes":["اكتبوا البرنامج `compter_mots.py`، دون نسخ ولصق","نفّذوه ودوّنوا السطرين المعروضين","فسّروا الفارق: لماذا 21 عنصرًا مقابل 19 كلمة؟","للأسرع: ابحثوا عن الكلمة الأكثر تواترًا (التمرين 3 من الأعمال الموجَّهة)"],"materiel":"البرنامج معروضًا على الشاشة؛ والأعمال الموجَّهة للفصل 2 على الموقع","notes":"يتبادل القائد والمساعد الدورين في منتصف النشاط. للأسرع، المنتظر: ثلاث كلمات متساوية، il وmon وcœur، مرتين لكل منها؛ و`Counter(mots).most_common(3)`، من الوحدة collections، تعطي `[('il', 2), ('mon', 2), ('cœur', 2)]`. ملاحظة قارئ تُشارَك مع الطلبة: يعدّ البرنامج «pleure» و«pleut» كلمتين لا علاقة بينهما؛ أما التقارب الصوتي الذي تقوم عليه القصيدة فيفلت من العدّ."},{"type":"code","titre":"compter_mots.py","code":"poeme = \"\"\"Il pleure dans mon cœur\nComme il pleut sur la ville ;\nQuelle est cette langueur\nQui pénètre mon cœur ?\"\"\"\n\nmots = poeme.lower().split()   # minuscules, puis découpage\nprint(len(mots), \"éléments\")   # « ; » et « ? » comptent aussi\nmots = [m for m in mots if m.isalpha()]  # lettres seulement\nprint(len(mots), \"mots,\", len(set(mots)), \"mots différents\")","sortie":"21 éléments\n19 mots, 16 mots différents","legende":"بول فيرلين، قصيدة «Il pleure dans mon cœur» من ديوان *Romances sans paroles* (1874)، المقطع الأول.","notes":"تسمح علامات التنصيص الثلاثية بكتابة نص على عدة أسطر. تحوّل `lower()` الأحرف إلى صغيرة، وتقطّع `split()` السلسلة عند المسافات وتُرجع قائمة. والتعبير `[m for m in mots if m.isalpha()]` بناءُ قائمة مختصر: «عناصر m من mots التي لا تحتوي إلا على حروف». وتحذف `set()` العناصر المكرَّرة: فيعطي طولها عدد الكلمات المختلفة."},{"type":"question","titre":"تفسير الفارق","question":"لماذا يجد البرنامج 21 عنصرًا مقابل 19 كلمة؟","reponse":"تقطّع `split()` السلسلة عند المسافات: فتصبح «;» و«?»، المسبوقتان بمسافة في الفرنسية، «كلمتين» إضافيتين.","explication":"لا تحتفظ `isalpha()` إلا بالعناصر المكوَّنة من حروف: فتختفي علامات الترقيم، وتبقى 19 كلمة.","notes":"اتركوا الطلبة يبحثون دقيقتين أو ثلاثًا. تلميح ممكن: عرض جزء من القائمة بواسطة `print(poeme.lower().split()[8:12])`، الذي يعطي `['sur', 'la', 'ville', ';']`. تضع قواعد الطباعة الفرنسية مسافة قبل «;» و«:»، فيعدّهما `split()` كلمتين. ومقارنة النصوص تفرض تحديد ما هي «الكلمة» قبل العدّ."},{"type":"tableau","titre":"أخطاء شائعة","entetes":["العَرَض","السبب","العلاج"],"lignes":[["`SyntaxError`","شيفرة منسوخة من Word أو من ملف PDF: علامات تنصيص طباعية “ ”","أعيدوا كتابة الشيفرة بعلامات تنصيص مستقيمة \" \""],["`NameError`","خلايا نُفِّذت دون ترتيب","أعيدوا تنفيذ الخلايا بالترتيب، من الأعلى إلى الأسفل"],["عنصر خاطئ","البحث عن العنصر الأول عند `[1]`","العنصر الأول هو `[0]`"]],"legende":"عادةٌ ينبغي اكتسابها: اقرؤوا أولًا السطر الأخير من رسالة الخطأ.","notes":"إن سمح الوقت، اعرضوا الخطأ الأول مباشرةً: `print(“Bonjour, Médéa !”)` بعلامات تنصيص طباعية تعطي `SyntaxError: invalid character '“' (U+201C)`. وللخطأ الثاني: خلية تستعمل mots قبل تنفيذ الخلية التي تُنشئ mots تعطي `NameError: name 'mots' is not defined`."},{"type":"question","titre":"الحصيلة","question":"ماذا تفعل `split()`؟","reponse":"تقطّع سلسلةً عند المسافات وتُرجع **قائمة** كلمات.","explication":"يعطي `\"Il pleure dans mon cœur\".split()` القائمة `['Il', 'pleure', 'dans', 'mon', 'cœur']`.","notes":"الحصيلة، 10 دقائق في المجموع. اختاروا بالقرعة الثنائي الذي يجيب: فعلى الجميع أن يكونوا مستعدين. وذكّروا بأن `split()` لا تعدّل السلسلة: بل تُرجع قائمة جديدة."},{"type":"question","titre":"الحصيلة","question":"ماذا يعني `NameError: name 'mots' is not defined`؟","reponse":"لا يعرف Python الاسم `mots`: فالمتغيّر لم يُنشأ (بعد).","explication":"في الدفتر التفاعلي، لم تُنفَّذ الخلية التي تُنشئ `mots`، أو نُفِّذت الخلايا دون ترتيب. وثمة سبب آخر: خطأ مطبعي في الاسم.","notes":"اربطوا ذلك بالخطأ الشائع في هذه الحصة. العلاج: إعادة تنفيذ الخلايا بالترتيب، من الأعلى إلى الأسفل."},{"type":"fin","titre":"قبل المغادرة","points":["احفظوا دفتركم التفاعلي (في Google Drive مع Colab)","أعيدوا كتابة أمثلة «أساسيات اللغة» مع توقّع كل مُخرَج","أنجزوا التمرين 1 من الأعمال الموجَّهة: الكلمات المتناظرة","برمجوا عشرين دقيقة، ثلاث مرات في الأسبوع"],"texte":"الحصة القادمة: استجواب مدوّنة نصية بمكتبة pandas.","notes":"تحقّقوا من أن كل ثنائي قد حفظ دفتره قبل مغادرة القاعة: فملفات جلسة Colab تُمحى عند إغلاقها. والأمثلة المطلوب إعادة كتابتها موجودة في درس «أساسيات اللغة» من الفصل 2؛ وللتمرين 1 من الأعمال الموجَّهة حلٌّ منشور على الموقع، لا يُفتح إلا بعد البحث."}]},{"id":"seance-5","numero":5,"titre":"أعمال تطبيقية: استجواب مدوّنة نصية بمكتبة pandas","resume":"تحميل ملف CSV وتصفيته وفرزه وتجميعه للإجابة عن سؤال مصوغ بلغة عادية، ثم رسم مخطط معنون وتأويله بحذر.","duree":"ساعة ونصف","lien":"cours.html#c2-numpy-pandas","fiche":"enseignant.html#guide-seance-5","diapos":[{"type":"titre","surtitre":"الفصل 2 · الحصة 5 · أعمال تطبيقية (TP)","titre":"استجواب مدوّنة نصية بمكتبة pandas","sousTitre":"عشرة أعمال، وستة أعمدة، وأسئلة مصوغة بلغة عادية","notes":"قبل الحصة، أودِعوا الملف oeuvres.csv، ملف الدرس الخاص بمكتبة pandas، حيث سيعمل الطلبة: في مجلد الدفتر التفاعلي مع Jupyter، وإلا ففي جلسة Colab. الثنائيات نفسها كما في الحصة 4، مع تبادل دورَي القائد والمساعد كل خمس عشرة دقيقة."},{"type":"points","titre":"أهداف الحصة","points":["تحميل ملف **CSV** ووصفه","**التصفية** و**الفرز** و**التجميع** للإجابة عن سؤال مصوغ بلغة عادية","رسم مخطط معنون و**تأويله بحذر**"],"notes":"أعلنوا خيط الحصة: السؤال بلغة عادية أولًا، ثم الشيفرة. وذكّروا منذ الآن بأن أعداد كلمات المدوّنة قيم مدوَّرة مختلَقة لأجل التمرين، وليست إحصاءات حقيقية."},{"type":"code","titre":"تذكير: التوقّع قبل التنفيذ","code":"vers = \"Il pleure dans mon cœur\"\nmots = vers.split()\nprint(len(mots), mots[0], mots[-1])","legende":"اكتبوا على الورق ما سيعرضه السطر الأخير، ثم نفّذوا.","notes":"10 دقائق. يكتب كل طالب توقّعه على الورق، منفردًا، قبل أي تنفيذ. ثم تكتب الثنائيات الأسطر الثلاثة وتقارن. والإجابة في الشريحة التالية."},{"type":"question","titre":"تذكير: الإجابة","question":"ماذا تعرض `print(len(mots), mots[0], mots[-1])`؟","reponse":"يُعرض `5 Il cœur`","explication":"تعطي `split()` 5 كلمات؛ الفهرس 0 يدلّ على الأولى، والفهرس `-1` على الأخيرة.","notes":"أخطاء متوقَّعة: «pleure» لـ `mots[0]`، إذا عُدّت الفهارس ابتداءً من 1، أو إجابة بين قوسين مربّعين. اطلبوا تسويغ كل قيمة من القيم الثلاث المعروضة."},{"type":"section","numero":1,"titre":"قراءة المدوّنة ووصفها","sousTitre":"من الجدول الإلكتروني إلى DataFrame","notes":"15 دقيقة."},{"type":"definition","terme":"DataFrame","traduction":"DataFrame","definition":"جدول في pandas مكوَّن من أعمدة (**Series**) تتقاسم الفهرس نفسه: وهو ما يعادل ورقة حساب.","exemple":"صف = عمل أدبي؛ عمود = متغيّر (العنوان، المؤلف، السنة، الجنس الأدبي، اللغة، عدد الكلمات).","notes":"افتحوا أولًا oeuvres.csv في برنامج جداول إلكترونية: إنه ملف نصي بسيط، فيه سطر لكل عمل، وأعمدة مفصولة بفواصل (CSV، comma-separated values). والـ DataFrame هو الجدول نفسه، داخل Python. أما الفهرس فهو تسميات الصفوف: 0، 1، 2… افتراضيًا."},{"type":"code","titre":"قراءة ملف CSV","code":"import pandas as pd\ndf = pd.read_csv(\"oeuvres.csv\", encoding=\"utf-8\")\nprint(df.shape)                     # (lignes, colonnes)\nprint(df[[\"titre\", \"annee\"]].head(4))","sortie":"(10, 6)\n               titre  annee\n0     Les Misérables   1862\n1  Les Fleurs du mal   1857\n2            Bel-Ami   1885\n3   La Grande Maison   1952","legende":"تعطي `shape` الأبعاد، و`head()` الصفوف الأولى (5 افتراضيًا).","notes":"تحمّل `import pandas as pd` المكتبة تحت اسمها المستعار المعتاد. اعتادوا كتابة `encoding=\"utf-8\"`، كما مع كل ملف في هذا المقياس. وفي الدفتر التفاعلي، تعرض `df.head()` وحدها في آخر سطر من الخلية جدولًا مقروءًا للصفوف الخمسة الأولى والأعمدة الستة. وإذا ردّ Python بالخطأ `FileNotFoundError`، فالملف ليس في مجلد الدفتر أو في جلسة Colab."},{"type":"tableau","titre":"ما تكشفه `info()`","entetes":["العمود","النوع (Dtype)","القيم غير الفارغة"],"lignes":[["titre","str","10"],["auteur","str","10"],["annee","int64","10"],["genre","str","10"],["langue","str","10"],["nb_mots","int64","10"]],"legende":"مخرجات `df.info()` مع pandas 3؛ ومع pandas 2، يظهر النص بالنوع `object` بدل `str`.","notes":"اطلبوا تنفيذ `df.info()`: يسرد هذا الأمر الأعمدة ونوع كل منها وعدد القيم غير الفارغة. وهنا 10 في كل مكان: لا بيانات ناقصة. يدلّ int64 على أعداد صحيحة، وstr على نص. وذكّروا مرة أخرى بأن أعداد الكلمات مختلَقة: نتعلّم منهجًا، لا حقائق عن هذه الأعمال."},{"type":"section","numero":2,"titre":"استجواب المدوّنة","sousTitre":"التصفية، والفرز، والتجميع، والرسم","notes":"20 دقيقة للتصفية والفرز، و20 دقيقة للتجميع، و15 دقيقة للرسم البياني."},{"type":"question","titre":"السؤال أولًا، بلغة عادية","question":"ما أعمال المدوّنة المكتوبة بالعربية والصادرة بعد 1950؟","reponse":"العملان *Bayn al-Qasrayn* (1956) و*Awraq al-Zaytun* (1964).","explication":"صحيح أن *Al-Ayyam* (1929) مكتوب بالعربية، لكنه صدر قبل 1950: فلا بدّ من تحقّق **شرطين** معًا.","notes":"اطلبوا أولًا الإجابة يدويًا، بالنظر إلى الجدول المعروض: فالسؤال هو الذي يوجّه الشيفرة، لا العكس. ثم اسألوا أيّ الأعمدة ينبغي استجوابها. المنتظر: langue وannee."},{"type":"code","titre":"ترجمة السؤال إلى شرط تصفية","code":"choix = df[(df[\"langue\"] == \"arabe\") & (df[\"annee\"] > 1950)]\nprint(choix[[\"titre\", \"annee\"]])","sortie":"             titre  annee\n6  Bayn al-Qasrayn   1956\n7  Awraq al-Zaytun   1964","legende":"ضعوا كل شرط بين قوسين؛ `&` تعني «و»، و`|` تعني «أو».","notes":"يُنتج كل شرط عمودًا من True وFalse؛ وتحتفظ `df[condition]` بالصفوف الصحيحة. ويُحتفَظ بالفهرس الأصلي (6، 7). فخّ شائع: `and` بدل `&`، مما يُحدث `ValueError: The truth value of a Series is ambiguous…`. ونسيان القوسين حول كل شرط يُحدث خطأً أيضًا."},{"type":"code","titre":"الفرز بواسطة `sort_values()`","code":"plus_longs = df.sort_values(\"nb_mots\", ascending=False)\nprint(plus_longs[[\"titre\", \"nb_mots\"]].head(3))","sortie":"             titre  nb_mots\n0   Les Misérables   530000\n6  Bayn al-Qasrayn   160000\n2          Bel-Ami   125000","legende":"مع `ascending=False` يكون الترتيب تنازليًا، من الأطول إلى الأقصر.","notes":"السؤال بلغة عادية أولًا: «ما الأعمال الثلاثة الأطول؟». ومن دون `ascending=False`، يكون الفرز تصاعديًا. وللأسرع: فرز نتيجة التصفية السابقة بحسب السنة، بواسطة `choix.sort_values(\"annee\")`."},{"type":"code","titre":"التجميع بواسطة `groupby()`","code":"# Nombre moyen de mots pour chaque genre, arrondi\nprint(df.groupby(\"genre\")[\"nb_mots\"].mean().round())","sortie":"genre\npoésie     28333.0\nroman     174500.0\nrécit      48000.0\nName: nb_mots, dtype: float64","legende":"توزّع `groupby` الصفوف بحسب الجنس الأدبي، ثم تحسب متوسط كل مجموعة.","notes":"اقرؤوا السطر كجملة: «جمّع بحسب الجنس، وخذ العمود nb_mots، واحسب متوسطه، وقرّبه». رُتِّب «récit» بعد «roman»: إذ يرتّب Python السلاسل بحسب رقم Unicode لمحارفها، والحرف «é» يأتي بعد جميع الحروف الخالية من العلامات. ومن دون `round()`، لظهر متوسط الشعر (poésie) بالقيمة `28333.333333`."},{"type":"code","titre":"العدّ بواسطة `value_counts()`","code":"print(df[\"genre\"].value_counts())   # effectifs par genre","sortie":"genre\nroman     6\npoésie    3\nrécit     1\nName: count, dtype: int64","legende":"تكرارات كل قيمة، من الأكثر تواترًا إلى الأندر.","notes":"تعدّ `value_counts()` مرات ورود كل قيمة. والحركة نفسها على اللغة: `df[\"langue\"].value_counts()` تعطي français 5، وarabe 3، وanglais 2. نبّهوا إلى العدد 1 الخاص بالسرد (récit): فهو يمهّد للسؤال التالي."},{"type":"question","titre":"التأويل بحذر","question":"للجنس «récit» (السرد) متوسط قدره 48 000 كلمة. ما قيمة هذا الرقم؟","reponse":"لا تكاد تُذكر: فهو يستند إلى نص **واحد** فقط، هو *Al-Ayyam*.","explication":"الحساب الدقيق لا يصنع استنتاجًا متينًا: قبل أي متوسط، انظروا إلى عدد النصوص التي يلخّصها.","notes":"اتركوا الثنائيات تتناقش دقيقة واحدة. للتوسّع: ثلاثة دواوين شعرية لا تكفي كذلك للحديث عن «الشعر» عمومًا. وعشرة أعمال اختيرت لأجل تمرين لا تمثّل أي أدب."},{"type":"chiffre","valeur":"530 000","legende":"كلمة في *Les Misérables* (قيمة مختلَقة): فيرتفع متوسط المدوّنة إلى 118 000 كلمة، ويبقى الوسيط عند 68 500.","source":"مدوّنة تمرين الفصل 2 (أعداد كلمات مختلَقة)","notes":"اطلبوا الحساب: `df[\"nb_mots\"].mean()` تعطي `118000.0`، و`df[\"nb_mots\"].median()` تعطي `68500.0`. يقسم الوسيط السلسلة إلى نصفين؛ ورواية واحدة طويلة جدًا ترفع المتوسط. والأثر نفسه على الروايات: 174 500 كلمة في المتوسط مع Les Misérables، و103 400 من دونها، أي مجموع الروايات (1 047 000) مطروحًا منه 530 000، مقسومًا على 5. ما ينبغي تذكّره: أمام نصوص متفاوتة الطول، انظروا دائمًا إلى الوسيط."},{"type":"code","titre":"مخطط بالأشرطة","code":"import matplotlib.pyplot as plt\nmoyennes = df.groupby(\"genre\")[\"nb_mots\"].mean()\nmoyennes.plot(kind=\"bar\")            # diagramme en barres\nplt.title(\"Longueur moyenne des œuvres par genre\")\nplt.xlabel(\"Genre\")\nplt.ylabel(\"Nombre de mots (valeurs fictives)\")\nplt.tight_layout()\nplt.savefig(\"mots_par_genre.png\")    # enregistrer l'image\nplt.show()                           # l'afficher","legende":"ثلاثة أشرطة، واحد لكل جنس (poésie، roman، récit): ويتفوّق شريط الرواية بوضوح.","notes":"15 دقيقة. العنوان وأسماء المحاور ليست للزينة: فمن دونها يتعذّر تأويل الرسم البياني. وتحفظ `savefig()` صورة PNG يمكن إدراجها في مذكرة؛ اطلبوا من الطلبة العثور على الملف في مجلد الدفتر أو في جلسة Colab. واسألوا: ماذا يُظهر شريط الرواية، وماذا يُخفي؟ المنتظر: ثقل Les Misérables."},{"type":"activite","titre":"الحصيلة: «في هذه المدوّنة الصغيرة…»","duree":10,"consignes":["يكتب كل ثنائي جملة تبدأ بـ«في هذه المدوّنة الصغيرة…»","تستند الجملة إلى نتيجة معروضة: تصفية، أو متوسط، أو تعداد، أو رسم بياني","لا تعمّم الجملة أبعد من الأعمال العشرة","ثم ابدؤوا التمرين 4 من الأعمال الموجَّهة: تصفية ثمانية نصوص وتجميعها وفرزها"],"materiel":"الأعمال الموجَّهة للفصل 2، التمرين 4، على الموقع","notes":"اطلبوا قراءة جملتين أو ثلاث وصحّحوا التعميمات: فعشرة أعمال وأعداد مختلَقة لا تسمح بأي استنتاج عام. ولكم أنتم أجوبة التمرين 4: الروايات التي يزيد عدد كلماتها على 70 000 هي T2 وT3 وT8؛ وبحسب اللغة: الإنجليزية نصّان بمتوسط 46 750 كلمة، والعربية 3 نصوص بمتوسط 24 067، والفرنسية 3 بمتوسط 52 300؛ وأقصر ثلاثة نصوص هي T5 وT1 وT7."},{"type":"tableau","titre":"أخطاء شائعة","entetes":["العَرَض","السبب","العلاج"],"lignes":[["`FileNotFoundError`","ملف CSV ليس في مجلد الدفتر ولا في جلسة Colab","ضعوا الملف في المكان الصحيح، وتحقّقوا من اسمه"],["عمود واحد فقط","ملف CSV محفوظ ببرنامج Excel مضبوط على الفرنسية","اقرؤوه بـ `pd.read_csv(\"oeuvres.csv\", sep=\";\")`"],["`KeyError`","كتابة `df[\"genre\", \"titre\"]`","اكتبوا `df[[\"genre\", \"titre\"]]` بقوسين مربّعين مضاعفين"],["`ValueError`","استعمال `and` بين شرطين","استعملوا `&`، مع وضع كل شرط بين قوسين"]],"notes":"كثيرًا ما يفصل Excel المضبوط على الفرنسية بين الأعمدة بفواصل منقوطة: فتعرض `shape` حينئذ `(10, 1)` بدل `(10, 6)`. ونحصل على عمود واحد بقوسين مربّعين بسيطين، وعلى عدة أعمدة بقائمة من الأسماء، ومن هنا القوسان المربّعان المضاعفان."},{"type":"fin","titre":"العمل الشخصي","points":["أتمّوا التمرين 4 من الأعمال الموجَّهة بعد عشرين دقيقة من البحث دون الاطلاع على الحل","أضيفوا ثلاثة أعمال إلى ملف CSV ودوّنوا ما يتغيّر في النتائج"],"texte":"الحصة القادمة: الأعمال الموجَّهة للفصل 3، النظام الخبير والتسلسل الأمامي.","notes":"بخصوص إضافة الأعمال الثلاثة، انصحوا بمراقبة المتوسط والوسيط خاصة: فنصّ واحد طويل جدًا أو قصير جدًا يكفي لتحريكهما. وحلّ التمرين 4 منشور على الموقع، ولا يُفتح إلا بعد البحث."}]},{"id":"seance-6","numero":6,"titre":"أعمال موجَّهة: النظام الخبير والتسلسل الأمامي","resume":"تسمية المكوّنات الثلاثة للنظام الخبير، ورسم مخطط قواعد الأعمال الموجَّهة، وتنفيذ التسلسل الأمامي خطوة بخطوة مع تفسير سبب عدم تفعيل R4 وR7.","duree":"ساعة ونصف","lien":"cours.html#c3-symbolique","fiche":"enseignant.html#guide-seance-6","diapos":[{"type":"titre","surtitre":"الفصل 3 · الحصة 6 · أعمال موجَّهة (TD)","titre":"النظام الخبير والتسلسل الأمامي","sousTitre":"من قواعد العروض إلى التمرين 1 من الأعمال الموجَّهة","notes":"الوسائل: بطاقات القواعد السبع بمقاس A5 الخاصة بلعب الأدوار، ونص التمرين 1 من الأعمال الموجَّهة، وجهاز العرض للعرض التوضيحي. قسّموا السبورة إلى عمودين: «قاعدة الوقائع» و«القواعد المفعَّلة». المكتسبات القبلية: درس «الذكاء الاصطناعي الرمزي: الأنظمة الخبيرة»."},{"type":"points","titre":"أهداف الحصة","points":["تسمية **المكوّنات الثلاثة** للنظام الخبير","رسم **مخطط القواعد** في التمرين 1 من الأعمال الموجَّهة","تنفيذ **التسلسل الأمامي** خطوة بخطوة","تفسير سبب عدم تفعيل **R4** و**R7**"],"notes":"أعلنوا المسار: نمثّل الاستدلال أولًا بقواعد من الشعر، ثم نصوغه صياغة شكلية على تمرين الأعمال الموجَّهة، حيث الوقائع مجرّد حروف."},{"type":"question","titre":"تمهيد","question":"كيف تتعرّفون على السوناتة؟","reponse":"إذا كان في القصيدة 14 بيتًا ورباعيتان وثلاثيتان، فإنّها سوناتة.","explication":"كل إجابة مكتوبة على صيغة «إذا … فإنّ …» هي **قاعدة**: ومجموع القواعد يشكّل **قاعدة قواعد**.","notes":"10 دقائق. دوّنوا الإجابات على السبورة، ثم أعيدوا صياغتها مع القسم على صيغة «إذا … فإنّ». المنتظر أيضًا: 14 بيتًا و3 رباعيات وثنائية واحدة للسوناتة الإنجليزية، المسمّاة الشكسبيرية. وكتابٌ في علم العروض ينصّ على أن «السوناتة تتألف من أربعة عشر بيتًا موزّعة على رباعيتين وثلاثيتين» يصوغ قاعدةً بالفعل."},{"type":"definition","terme":"النظام الخبير","traduction":"système expert","definition":"برنامج من برامج الذكاء الاصطناعي الرمزي يحاكي استدلال مختصّ في مجال ضيّق، انطلاقًا من وقائع وقواعد يستطيع الإنسان قراءتها.","exemple":"كان MYCIN (ستانفورد، سبعينيات القرن العشرين) يشخّص الالتهابات البكتيرية في الدم ويقترح مضادًّا حيويًا.","notes":"يمثّل الذكاء الاصطناعي الرمزي المعرفةَ برموز مقروءة، أي بوقائع وقواعد، بدلًا من أعداد تُتعلَّم من البيانات. ويُعدّ DENDRAL (ستانفورد، ابتداءً من 1965) في الغالب أول نظام خبير؛ ولم يُستعمل MYCIN قطّ استعمالًا روتينيًا في المستشفى. نقطة قوة هذه المقاربة: قابلية التفسير، إذ تُسوَّغ كل نتيجة بالسلسلة الدقيقة للقواعد المفعَّلة."},{"type":"tableau","titre":"المكوّنات الثلاثة","entetes":["المكوّن","الدور","مثال"],"lignes":[["**قاعدة الوقائع**","ما نعرفه؛ وتتّسع كلما تقدّم الاستدلال","«القصيدة من 14 بيتًا»"],["**قاعدة القواعد**","المعارف: إذا مقدّمات فإنّ نتيجة","إذا 14 بيتًا ورباعيتان وثلاثيتان فإنّ سوناتة"],["**محرك الاستدلال**","يتعرّف على القواعد القابلة للتطبيق، ويفعّلها، ويضيف نتائجها","هو نفسه في الطب أو في الشعر"]],"notes":"لا يتوقّف محرك الاستدلال على المجال: ننتقل من الطب إلى الشعر بتغيير القواعد وحدها. وتُربط مقدّمات القاعدة بأداة «و» (ET)، ويُرمز إليها أيضًا بـ ∩ في نص الأعمال الموجَّهة؛ وسنكتبها ∧."},{"type":"tableau","titre":"قواعد الأشكال الشعرية","entetes":["القاعدة","إذا (المقدّمات)","فإنّ (النتيجة)"],"lignes":[["R1","3 أبيات ومقاطع 5-7-5","هايكو"],["R2","14 بيتًا ورباعيتان وثلاثيتان","سوناتة"],["R3","14 بيتًا و3 رباعيات وثنائية واحدة","سوناتة"],["R4","سوناتة وثلاثيتان","سوناتة إيطالية أو فرنسية"],["R5","سوناتة وثنائية واحدة","سوناتة إنجليزية"],["R6","سوناتة","شكل ثابت"],["R7","هايكو","شكل ثابت"]],"legende":"بحسب ترتيب الأولوية. الملاحظات («14 بيتًا»، «ثلاثيتان»…) وقائع غير قابلة للاستنتاج.","notes":"وزّعوا بطاقات القواعد السبع. تتألف السوناتة الإيطالية أو الفرنسية (بترارك، رونسار، بودلير) من رباعيتين وثلاثيتين؛ أما السوناتة الإنجليزية، المسمّاة الشكسبيرية، فمن ثلاث رباعيات وثنائية واحدة. ونبّهوا إلى أن القواعد من R4 إلى R7 تستعمل وقائع يجب أن تستنتجها قواعد أخرى أولًا."},{"type":"activite","titre":"لعب الأدوار: محرك الاستدلال","duree":20,"consignes":["يمثّل سبعة طلبة القواعد من R1 إلى R7؛ ويؤدي طالب آخر دور المحرك، وآخر دور الكاتب","على السبورة، قاعدة الوقائع الأولية: 14 بيتًا، رباعيتان، ثلاثيتان، أبيات إسكندرية","يستدعي المحرك القواعد بالترتيب، بدءًا من R1","تُفعَّل القاعدة إذا كانت كل مقدّماتها على السبورة وكانت نتيجتها جديدة","يكتب الكاتب النتيجة، وتجلس القاعدة، ونعود إلى R1","تتوقف اللعبة عند جولة كاملة لا تُفعَّل فيها أي قاعدة"],"materiel":"بطاقة بمقاس A5 لكل قاعدة؛ والسبورة مقسومة إلى «قاعدة الوقائع» و«القواعد المفعَّلة»","notes":"التوقيت: الأدوار 3 دقائق، والوقائع دقيقتان، والدورات 10 دقائق، ثم 5 دقائق لحالتين أخريين: قصيدة هايكو (R1 ثم R7) وسوناتة مطبوعة في كتلة واحدة، لا تُفعِّل أي قاعدة. وقاعدة الوقائع الأولية هي قاعدة سوناتة دو بيليه «Heureux qui, comme Ulysse, a fait un beau voyage» من ديوان Les Regrets (1558). الاستخلاص: «من كان يعرف أنها سوناتة؟» لا أحد: فكل قاعدة لم تكن تنظر إلا إلى السبورة."},{"type":"etapes","titre":"المنتظر: سوناتة دو بيليه","progressif":true,"etapes":[{"titre":"قاعدة الوقائع الأولية","texte":"14 بيتًا، رباعيتان، ثلاثيتان، أبيات إسكندرية"},{"titre":"الدورة 1","texte":"تفشل R1 (لا وجود لواقعة «3 أبيات»)؛ وتنطبق R2: نضيف «سوناتة»"},{"titre":"الدورة 2","texte":"نعود إلى R1؛ وتنطبق R4: «سوناتة إيطالية أو فرنسية»"},{"titre":"الدورة 3","texte":"تفشل R5 (لا وجود لواقعة «ثنائية واحدة»)؛ وتضيف R6 «شكل ثابت»"},{"titre":"الدورة 4: التوقّف","texte":"لم تعد أي قاعدة تُنتج واقعة جديدة"}],"notes":"القواعد المفعَّلة: R2 وR4 وR6؛ وثلاث وقائع مستنتَجة. لا تستعمل أي قاعدة واقعة «أبيات إسكندرية»: فتظل هذه الواقعة خاملة. ما ينبغي استخلاصه: يقارن المحرك رموزًا دون أن يفهمها؛ وترتيب القواعد يغيّر المسار؛ وخارج الحالات المتوقَّعة يفشل النظام."},{"type":"deux","titre":"تسلسل أمامي أم تسلسل خلفي؟","colonnes":[{"titre":"التسلسل الأمامي","points":["توجّهه **البيانات**: من الوقائع إلى الهدف","«ماذا يمكنني أن أستنتج؟»","عيبه: قد يستنتج كثيرًا من الوقائع غير المفيدة"]},{"titre":"التسلسل الخلفي","points":["يوجّهه **الهدف**: من الهدف إلى الوقائع","«ماذا أحتاج لإثبات هذا؟»","ميزته: لا تُفحص إلا القواعد المفيدة لبلوغ الهدف؛ ويلائم التشخيص"]}],"notes":"عرض مصغَّر: 10 دقائق مع الشريحة التالية. مثال على التسلسل الخلفي: الفرضية «سوناتة إنجليزية؟» تقتضي، بموجب R5، واقعتَي «سوناتة» و«ثنائية واحدة». والواقعة الأخيرة غير قابلة للاستنتاج وغائبة عن قاعدة الوقائع: فتُرفض الفرضية فورًا. المصطلحان بالإنجليزية: forward chaining وbackward chaining (وبالفرنسية: chaînage avant وchaînage arrière)."},{"type":"points","titre":"ترتيب القواعد والوقائع غير القابلة للاستنتاج","points":["**حلّ التعارض**: عدة قواعد قابلة للتطبيق، وعلى المحرك أن يختار واحدة منها","استراتيجية الأعمال الموجَّهة: **ترتيب للقواعد** محدَّد سلفًا","القاعدة التي فُعِّلت مرةً لا تُفعَّل مرة ثانية","**واقعة غير قابلة للاستنتاج**: لا تظهر في نتيجة أي قاعدة","لا يوفّرها سوى الملاحظة أو المستخدم: H وG وK في الأعمال الموجَّهة"],"notes":"في الدرس، يفعّل المحرك أول قاعدة قابلة للتطبيق وفق الترتيب، ثم يعود إلى بداية القائمة، كما في لعب الأدوار. أما حلّ الأعمال الموجَّهة فيمرّ على القواعد بالترتيب المفروض دون العودة إلى البداية: والنتيجة واحدة. وفي التسلسل الخلفي، إذا كان هدف فرعي غير قابل للاستنتاج وغائبًا عن قاعدة الوقائع، فشل هذا المسار، أو دفع النظامَ إلى سؤال المستخدم."},{"type":"section","titre":"التمرين 1 من الأعمال الموجَّهة","sousTitre":"سبع قواعد، وقاعدة الوقائع الأولية {H، K}، والهدف C","notes":"35 دقيقة: السؤال أ (15 دقيقة)، ثم السؤال ب (20 دقيقة)."},{"type":"tableau","titre":"نص التمرين: سبع قواعد","entetes":["القاعدة","إذا","فإنّ"],"lignes":[["R1","A","E"],["R2","B","D"],["R3","H","A ∧ F"],["R4","E ∧ G","C"],["R5","E ∧ K","B"],["R6","D ∧ E ∧ K","C"],["R7","G ∧ K ∧ F","A"]],"legende":"الترتيب: R3 R7 R1 R4 R5 R2 R6 · غير قابلة للاستنتاج: H، G، K · قاعدة الوقائع الأولية: {H، K} · الهدف: C","notes":"في نص البرنامج الرسمي، يُرمز إلى الوصل المنطقي بـ ∩: ويعني هذا الرمز هنا «و» (ET)، ونكتبه ∧. وتُقرأ «E ∧ G → C» كما يلي: إذا ثبتت E وG، فإن C تثبت. اطلبوا قراءة الترتيب بصوت مرتفع: فهو لا يتبع الترقيم."},{"type":"activite","titre":"السؤال أ: رسم المخطط","duree":15,"consignes":["**مستطيل** لكل واقعة، و**دائرة** لكل قاعدة","سهم من كل شرط نحو القاعدة، ثم من القاعدة نحو كل نتيجة من نتائجها","الأسهم التي تدخل القاعدة نفسها: شروط مرتبطة بـ«و»","قاعدتان تؤدّيان إلى الواقعة نفسها (R3 وR7 إلى A، وR4 وR6 إلى C): «أو»","حدّدوا الوقائع التي لا يصل إليها أي سهم"],"notes":"نتحدث عن مخطط «و/أو» (graphe ET/OU). عمل فردي أو ثنائي، ثم تصحيح على السبورة. حيلة في الإخراج مأخوذة من الحل: وضع H تحت R3 حتى لا يتقاطع أي سهم مع سهم آخر. والمخطط المصحَّح موجود في الأعمال الموجَّهة على الموقع."},{"type":"question","titre":"السؤال أ: تشخيص أولي","question":"ما الوقائع التي لا يصل إليها أي سهم؟ وماذا نستنتج من ذلك؟","reponse":"إنها G وH وK: الوقائع غير القابلة للاستنتاج. وبما أن G ليست في قاعدة الوقائع الأولية، فلن تُفعَّل R4 وR7 أبدًا.","explication":"فالمسار الوحيد الممكن نحو C يمرّ إذن عبر R6.","notes":"اتركوا الطلبة يصوغون الاستنتاج بأنفسهم. توفّر قاعدةُ الوقائع الأولية H وK؛ أما G فغائبة، ولا يمكن لأي قاعدة أن تُنتجها. هذا هو مفتاح التمرين كلّه."},{"type":"activite","titre":"السؤال ب: تنفيذ التسلسل الأمامي","duree":20,"consignes":["افحصوا القواعد بالترتيب المفروض: R3، R7، R1، R4، R5، R2، R6","تُفعَّل القاعدة إذا كانت **كل** شروطها في قاعدة الوقائع","أضيفوا **كل** نتائجها إلى قاعدة الوقائع","لا تُعاد القاعدة التي سبق تفعيلها","توقّفوا حالما تصبح C في قاعدة الوقائع، أو حين لا يضيف مرورٌ كامل أي شيء"],"materiel":"شبكة لكل طالب: المرحلة، والقاعدة المفحوصة، والشرط، ومُفعَّلة؟، وقاعدة الوقائع بعدها","notes":"يملأ كل طالب شبكته منفردًا، خطوة بخطوة؛ ثم يجري التصحيح على السبورة. تجوّلوا وراقبوا: تفعيل R7 مع غياب G، ونسيان F بعد R3، وإعادة تفعيل قاعدة، واتّباع ترتيب الترقيم بدل الترتيب المفروض."},{"type":"tableau","titre":"السؤال ب: الحل","entetes":["المرحلة","القاعدة","الشرط","مُفعَّلة؟","قاعدة الوقائع بعدها"],"lignes":[["1","R3","H","نعم: H موجودة في قاعدة الوقائع","H، K، A، F"],["2","R7","G ∧ K ∧ F","لا: G غائبة","H، K، A، F"],["3","R1","A","نعم","H، K، A، F، E"],["4","R4","E ∧ G","لا: G غائبة","H، K، A، F، E"],["5","R5","E ∧ K","نعم","H، K، A، F، E، B"],["6","R2","B","نعم","H، K، A، F، E، B، D"],["7","R6","D ∧ E ∧ K","نعم","H، K، A، F، E، B، D، C: تم بلوغ الهدف"]],"legende":"القواعد المفعَّلة: R3، R1، R5، R2، R6. قاعدة الوقائع النهائية: {H، K، A، F، E، B، D، C}.","notes":"يثبت الهدف C منذ المرور الأول على القواعد. ولا تُفعَّل R4 وR7 أبدًا، لأن G ليست في قاعدة الوقائع الأولية ولا يمكن استنتاجها. صيغة بديلة: إذا عاد المحرك إلى القاعدة الأولى بعد كل تفعيل، كما في لعب الأدوار، نحصل على التفعيلات نفسها وعلى قاعدة الوقائع النهائية نفسها؛ ولا يزداد إلا عدد القواعد التي يُمرّ عليها."},{"type":"question","titre":"عرض توضيحي: وماذا لو كانت G معروفة؟","question":"نضيف G إلى قاعدة الوقائع الأولية: {H، K، G}. ماذا يحدث؟","reponse":"يُبلَغ الهدف C أبكر، عبر **R4**: R3، ثم R1، ثم R4، لأن E وG معروفتان.","explication":"تصبح R7 قابلة للتطبيق، لكنها لا تضيف شيئًا جديدًا: فـ A موجودة من قبل في قاعدة الوقائع.","notes":"10 دقائق. افتحوا العرض التفاعلي في درس «الذكاء الاصطناعي الرمزي: الأنظمة الخبيرة»: H وK مؤشَّر عليهما؛ تقدّموا بالزر «افحص القاعدة التالية» واطلبوا التعليق على كل مرحلة. ثم اطلبوا توقّع أثر G قبل التأشير على خانتها. يَسِم العرض حينئذ R7 بأنها «بلا فائدة»؛ أما برنامج Python في الأعمال الموجَّهة فيعدّها مفعَّلة (R3، R7، R1، R4). وفي الحالتين، يُبلَغ C عبر R4."},{"type":"points","titre":"أخطاء شائعة","points":["تفعيل قاعدة لا يُعرف إلا جزء من مقدّماتها","نسيان إحدى نتيجتَي R3: A **و** F","إعادة تفعيل قاعدة، أو تجاهل الترتيب المفروض","محاولة استنتاج G: فهي واقعة غير قابلة للاستنتاج"],"notes":"عودوا إلى هذه الأخطاء انطلاقًا من الشبكات التي لاحظتموها خلال السؤال ب. واسألوا القسم، في كل مرة، عن تعليمة المحرك التي نُسيت."},{"type":"question","titre":"الحصيلة","question":"في جملة واحدة: ما الفرق بين التسلسل الأمامي والتسلسل الخلفي؟","reponse":"ينطلق التسلسل الأمامي من الوقائع المعروفة ويطبّق القواعد إلى أن يبلغ الهدف؛ أما التسلسل الخلفي فينطلق من الهدف ويعود نحو الوقائع اللازمة لإثباته.","notes":"5 دقائق. يكتب كل طالب جملته على ورقة قبل كشف الإجابة؛ اجمعوها بوصفها بطاقة خروج: فهي ستخبركم إن كان المفهوم قد اكتُسب."},{"type":"fin","titre":"العمل الشخصي","points":["أعيدوا إنجاز التمرين 1 دون الاستعانة بالحل، بعد ثلاثة أيام","اكتبوا خمس قواعد تميّز بين الخرافة والحكاية والقصة القصيرة","طبّقوها بالتسلسل الأمامي على نصّين معروفين"],"texte":"الحصة القادمة: التعلم الآلي.","notes":"بخصوص القواعد الخمس، ذكّروا بنموذج الحصة: مقدّمات قابلة للملاحظة (الطول، ووجود مغزى أخلاقي، والشخصيات، والعجائبي…) ونتيجة. وأمام نصوص حقيقية، سيلاحظ الطلبة هشاشة القواعد خارج الحالات المتوقَّعة: وهذا هو حدّ الأنظمة الخبيرة الذي يبرزه الدرس."}]},{"id":"seance-7","numero":7,"titre":"التعلم الآلي: k-المتوسطات، والانحدار، والانحدار التدرّجي","resume":"تعريف مفردات التعلم الآلي، وتنفيذ خوارزمية k-المتوسطات يدويًا حتى التوقف، وحساب خطوتين من الانحدار التدرّجي مع شرح دور معدل التعلم.","duree":"ساعة ونصف","lien":"cours.html#c3-algorithmes","fiche":"enseignant.html#guide-seance-7","diapos":[{"type":"titre","surtitre":"الفصل 3 · الحصة 7","titre":"التعلم الآلي","sousTitre":"خوارزمية k-المتوسطات، والانحدار الخطي، والانحدار التدرّجي","notes":"حصة مدتها ساعة ونصف في ست مراحل: من القواعد إلى الأمثلة (10 دقائق)، وخوارزمية k-المتوسطات يدويًا (20)، وعرض توضيحي (10)، والانحدار (15)، والانحدار التدرّجي (25)، والحصيلة (10). المكتسبات القبلية: الحصتان 3 و6، ومعرفة حساب المتوسط. تحقّقوا قبل الدرس من أن لدى كل طالب آلة حاسبة، ومن أن العروض التوضيحية في درس «بعض خوارزميات التعلم الآلي» تُفتح على حاسوب القاعة."},{"type":"points","titre":"أهداف الحصة","points":["تعريف **السمات** و**الوسم** و**النموذج** و**التدريب** و**الاختبار**","تنفيذ **خوارزمية k-المتوسطات** يدويًا حتى التوقف","حساب خطوتين من **الانحدار التدرّجي**","شرح دور **معدل التعلم** η"],"notes":"اقرؤوا الأهداف بصوت مرتفع: إنها أفعال إجرائية يمكن التحقق منها قبل نهاية الحصة. وأعلنوا الطريقة: تُنجَز كل خوارزمية يدويًا أولًا، على أعداد صغيرة جدًا، ثم على العرض التوضيحي في الموقع. «إذا استطعتم إعادة الحساب يدويًا، فقد فهمتم الخوارزمية.»"},{"type":"question","titre":"من القواعد إلى الأمثلة · 10 دقائق","question":"هل تستطيعون كتابة القواعد التي تجعلكم تتعرّفون على نثر كاتب ياسين؟","reponse":"بصعوبة: نتعرّف عليه من بضعة أسطر، من دون أن نقدر على تعداد القواعد التي يقوم عليها هذا الحكم.","explication":"كان النظام الخبير في الحصة 6 يقتضي قواعد تُكتب يدويًا. أما التعلم الآلي فيقلب المسار: نزوّد البرنامج بأمثلة، فيستخرج منها بنفسه الانتظامات.","notes":"امنحوا الطلبة دقيقتين أو ثلاثًا. دوّنوا على السبورة «القواعد» التي يقترحونها، واجعلوهم يلاحظون أنها تظل مبهمة أو ناقصة. ثم اكشفوا الإجابة. الانتقال: كثير من المعارف يستعصي على الصياغة في قواعد؛ ومن هنا ينطلق التعلم الآلي."},{"type":"definition","terme":"التعلم الآلي","traduction":"apprentissage automatique","definition":"نزوّد البرنامج بأمثلة، فيستخرج منها بنفسه الانتظامات. والتعلّم هو ضبط **معاملات** النموذج، أي أعداد، إلى أن يعيد إنتاج الأمثلة المعروفة على أفضل وجه.","exemple":"تعريف Tom Mitchell (1997)، بتصرّف: يتعلّم البرنامج حين يتحسّن أداؤه في مهمّة ما بفعل التجربة.","notes":"ألحّوا على كلمة «المعاملات»: إنها أعداد، لا قواعد. وتعرض الحصة كلها طرقًا لإيجاد أعداد: مراكز المجموعات في خوارزمية k-المتوسطات، والميل والقيمة الثابتة في الانحدار، وخطوات متتالية في الانحدار التدرّجي."},{"type":"tableau","titre":"المفردات، على مثال مرشِّح الرسائل المزعجة","entetes":["المصطلح","بالإنجليزية","في مرشِّح الرسائل المزعجة"],"lignes":[["السمات","features","عدد الكلمات، ووجود كلمة «مجاني»"],["الوسم","label","«مزعج» أو «غير مزعج» (في التعلم الخاضع للإشراف فقط)"],["النموذج","model","الصيغة التي تحوّل السمات إلى تنبّؤ"],["التدريب","training","ضبط المعاملات على أمثلة"],["مجموعة الاختبار","test set","رسائل لم يرها النموذج قطّ، لتقييم التنبّؤات"]],"legende":"نقسّم المدوّنة: غالبًا من 70 إلى 80% من الأمثلة للتدريب، والباقي للاختبار.","notes":"اطلبوا من الطلبة إيجاد مثال كل سطر قبل عرضه. نقطة أساسية: لا يُقيَّم نموذج أبدًا على الأمثلة التي استُعملت في تدريبه، كما لا يُمتحن طالب في أسئلة يحفظ أجوبتها عن ظهر قلب. ووضّحوا أن الوسم لا يوجد إلا في التعلم الخاضع للإشراف: فخوارزمية k-المتوسطات، التي تأتي بعد ذلك مباشرة، لا وسم فيها."},{"type":"section","numero":1,"titre":"خوارزمية k-المتوسطات يدويًا","sousTitre":"التمرين 2 د · 20 دقيقة","notes":"ذكّروا بالمبدأ: تكوين مجموعات من الأشياء المتشابهة من دون أي وسم. إنه تعلّم غير خاضع للإشراف، وهو أداة الموضوع 2 من المشروع المصغَّر حول الاستبيانات."},{"type":"activite","titre":"التمرين 2 د: ست شخصيات، ومجموعتان","duree":15,"consignes":["ست شخصيات في مسرحية، لها على التوالي 1 و3 و4 و9 و10 و14 ردًّا حواريًا (بيانات افتراضية).","ضعوها على مستقيم مدرَّج؛ عدد المجموعات k = 2، والمركزان الأوليان μ₁ = 1 وμ₂ = 4.","**الإسناد**: تنضمّ كل نقطة إلى المركز الأقرب إليها.","**إعادة الحساب**: يصبح كل مركز متوسطَ نقاط مجموعته.","أعيدوا الكرّة إلى أن لا تغيّر أي نقطة مجموعتها."],"materiel":"آلة حاسبة؛ مستقيم مدرَّج من 0 إلى 15 على السبورة","notes":"ارسموا المستقيم واطلبوا من أحد الطلبة وضع النقاط الست. تجوّلوا بين الطلبة أثناء الحساب: الخطأ الأكثر شيوعًا هو التوقف بعد تكرار واحد، أو نسيان إعادة حساب المراكز. احتفظوا بخمس دقائق للتصحيح."},{"type":"tableau","titre":"التصحيح: ثلاثة تكرارات","entetes":["التكرار","المراكز","المجموعة 1","المجموعة 2","المراكز الجديدة"],"lignes":[["1","μ₁ = 1 ; μ₂ = 4","{1}","{3, 4, 9, 10, 14}","1 و40 / 5 = 8"],["2","μ₁ = 1 ; μ₂ = 8","{1, 3, 4}","{9, 10, 14}","8/3 ≈ 2,67 و33 / 3 = 11"],["3","μ₁ ≈ 2,67 ; μ₂ = 11","{1, 3, 4}","{9, 10, 14}","المجموعات لم تتغيّر: التوقف"]],"legende":"النتيجة: {1, 3, 4}، أي الأدوار الثانوية، و{9, 10, 14}، أي الأدوار الرئيسية.","notes":"صحّحوا سطرًا سطرًا، واطلبوا من الطلبة إملاء المسافات. التكرار 2: تنتقل 3 إلى المجموعة 1 (المسافتان 2 و5)، وكذلك 4 (3 و4)؛ وتبقى 9 و10 و14 في المجموعة 2 (مسافاتها إلى 8: 1 و2 و6). التكرار 3: المسافات إلى 8/3 نحو 1,67 و0,33 و1,33، والمسافات إلى 11 هي 2 و1 و3: لا شيء يتحرك، فتتوقف الخوارزمية. نبّهوا إلى أن تكرارًا واحدًا لم يكن كافيًا: فبعد التكرار الأول، كانت المجموعة 2 لا تزال تخلط أدوارًا مختلفة جدًا."},{"type":"question","titre":"عرض توضيحي · 10 دقائق","question":"أعيدوا تشغيل العرض التوضيحي انطلاقًا من مراكز أولية أخرى: هل نحصل دائمًا على المجموعات نفسها؟","reponse":"ليس دائمًا: فالنتيجة تتوقف على نقطة الانطلاق، كما تتوقف على اختيار k.","explication":"تقيس الخوارزمية مسافات وتحسب متوسطات، من دون أن تفهم شيئًا عن البيانات. ولذلك يعيد scikit-learn تشغيلها من عدة نقاط انطلاق (`n_init`) ويحتفظ بأفضل حل. أما تسمية المجموعات فتظل من عمل الباحث.","notes":"افتحوا العرض التوضيحي لخوارزمية k-المتوسطات في درس «بعض خوارزميات التعلم الآلي». قبل كل نقرة على «الخطوة التالية»، اطلبوا من الطلبة توقّع التوزيع؛ ثم اسحبوا مراكز جديدة وقارنوا. صيغة مطوّلة ممكنة (40 دقيقة): نشاط بطاقات الروايات في الدليل، حيث يؤدي الانطلاق من E وH وI إلى حل رديء."},{"type":"section","numero":2,"titre":"الانحدار الخطي","sousTitre":"التمرين 2 أ · 15 دقيقة","notes":"تغيير العائلة: نعود إلى التعلم الخاضع للإشراف. لم يعد الأمر يتعلق بتكوين مجموعات، بل بالتنبؤ بعدد انطلاقًا من أمثلة نعرف إجابتها."},{"type":"activite","titre":"مستقيم يُرسم بالعين","duree":5,"consignes":["خمسة طلبة (بيانات افتراضية): x = ساعات القراءة في الأسبوع، وy = الكتب المقروءة خلال السداسي.","النقاط: (1 ; 2)، (2 ; 3)، (3 ; 5)، (4 ; 4)، (5 ; 6).","ضعوها في معلم، وارسموا بالعين المستقيم الذي يمرّ بأقرب ما يمكن منها.","قارنوا مع جاركم: أيّ مستقيم هو الأفضل، ووفق أيّ معيار؟"],"materiel":"ورقة ومسطرة","notes":"اتركوا الطلبة يرسمون دون صيغة. تختلف المستقيمات من طالب إلى آخر: وهي فرصة لطلب معيار موضوعي. المنتظر: المستقيم الذي تكون فروقه عن النقاط أصغر ما يمكن. وهذا هو الانتقال نحو المربعات الصغرى."},{"type":"definition","terme":"الانحدار الخطي","traduction":"régression linéaire","definition":"التنبؤ بعدد بواسطة المستقيم ŷ = w · x + b. وتختار طريقة **المربعات الصغرى** قيمتَي w وb بحيث يكون متوسط مربعات الفروق (yᵢ − ŷᵢ)² أصغر ما يمكن.","exemple":"في التمرين 2 أ، يُرمز إلى الميل بـ a: ŷ = a · x + b.","notes":"تُقرأ ŷ «y chapeau»: إنها القيمة المتوقَّعة. w هو الميل، وb قيمة الانطلاق. يمنع التربيع الفروق الموجبة والسالبة من أن يعوّض بعضها بعضًا، ويعاقب الأخطاء الكبيرة. لا داعي لإجراء الحساب كاملًا في القسم: أعطوا النتيجة (الشريحة التالية)؛ فالحساب الكامل جزء من العمل الشخصي."},{"type":"chiffre","valeur":"6,7 كتب","legende":"متوقَّعة مقابل 6 ساعات قراءة في الأسبوع: ŷ = 0,9 × 6 + 1,3، مع a = 0,9 وb = 1,3","source":"التمرين 2 أ · بيانات افتراضية","notes":"الحساب، إن طُلب منكم: x̄ = 3 وȳ = 4؛ Σ(x − x̄)(y − ȳ) = 9 وΣ(x − x̄)² = 10، إذن a = 9 / 10 = 0,9 وb = 4 − 0,9 × 3 = 1,3. القراءة: ترتبط كل ساعة أسبوعية إضافية بزيادة قدرها 0,9 كتاب على مدى السداسي، في هذه البيانات الافتراضية. تنبيه: القيمة x = 6 تخرج عن المجال الملاحَظ (من 1 إلى 5)، فهذا استقراء خارجي. خطأ شائع: تمديد المستقيم بعيدًا عن البيانات الملاحَظة."},{"type":"section","numero":3,"titre":"الانحدار التدرّجي","sousTitre":"التمرين 2 ب · 25 دقيقة","notes":"سؤال افتتاحي: لا تُحلّ معظم النماذج دفعة واحدة؛ فكيف نجد معاملاتها؟ الإجابة: بخطوات صغيرة، بواسطة الانحدار التدرّجي."},{"type":"deux","titre":"المتنزّه في الضباب","colonnes":[{"titre":"المتنزّه","points":["لا يرى الوادي","يحسّ بالمنحدر تحت قدميه","يخطو في كل مرة خطوة نحو الأسفل","يضبط طول خطوته"]},{"titre":"الخوارزمية","points":["الوادي: دالة الكلفة J(w)، التي تقيس الخطأ","المنحدر: التدرّج، أي مشتقة J","الخطوة: w ← w − η · الميل","العدد η (إيتا): **معدل التعلم** (*taux d'apprentissage*)"]}],"progressif":true,"notes":"احكوا الاستعارة، ثم أظهروا الأسطر واحدًا تلو الآخر. يعني السهم «استبدِل بـ». النقطة الدقيقة هي الإشارة: إذا كان الميل موجبًا، تتناقص w؛ وإذا كان سالبًا، تتزايد w. وفي الحالتين، ننزل. صيغة مطوّلة ممكنة: نشاط الأوراق الإحدى عشرة الموضوعة على الأرض (الدليل، 25 دقيقة)."},{"type":"activite","titre":"التمرين 2 ب ضمن ثنائيات","duree":10,"consignes":["الدالة J(w) = (w − 3)² تبلغ حدّها الأدنى عند w = 3؛ ومشتقتها J′(w) = 2(w − 3).","الانطلاق من w₀ = 0؛ ومعدل التعلم η = 0,1.","احسبوا w₁ وw₂ بالعلاقة wₖ₊₁ = wₖ − η · J′(wₖ).","احسبوا J(w₀) وJ(w₁) وJ(w₂). نحو أي قيمة تتجه المتتالية؟"],"materiel":"آلة حاسبة","notes":"المشتقة معطاة: نحن نقيّم الخوارزمية، لا الحساب التفاضلي. تجوّلوا وراقبوا الإشارة: 0 − 0,1 × (−6) تعطي فعلًا +0,6. أما الثنائيات التي تنتهي مبكرًا فتحسب w₃."},{"type":"tableau","titre":"تصحيح التمرين 2 ب","entetes":["الخطوة k","wₖ","J(wₖ)","الميل J′(wₖ)","wₖ₊₁ = wₖ − 0,1 × J′(wₖ)"],"lignes":[["0","0","9","2 × (0 − 3) = −6","0 + 0,6 = 0,6"],["1","0,6","5,76","2 × (0,6 − 3) = −4,8","0,6 + 0,48 = 1,08"],["2","1,08","3,6864 ≈ 3,69","2 × (1,08 − 3) = −3,84","1,08 + 0,384 = 1,464"]],"legende":"ينخفض الخطأ مع كل خطوة. وتُضرب المسافة إلى الحدّ الأدنى في 0,8 (3 ؛ 2,4 ؛ 1,92…): فتتجه المتتالية نحو w = 3.","notes":"اطلبوا قراءة العمود J: 9، ثم 5,76، ثم نحو 3,69؛ فالخطأ يتناقص. ويأتي المعامل 0,8 من إعادة كتابة القاعدة: wₖ₊₁ − 3 = (1 − 2η)(wₖ − 3) = 0,8 (wₖ − 3). ويذهب السطر الأخير خطوةً أبعد مما يطلبه نص التمرين: w₃ = 1,464، كما في الحل."},{"type":"tableau","titre":"عرض توضيحي: تغيير الخطوة η","entetes":["η","قيم w انطلاقًا من 0","ما يحدث"],"lignes":[["0,1","0,6 ؛ 1,08 ؛ 1,464…","تقترب w من 3: الخوارزمية تتقارب"],["1,1","6,6 ؛ −1,32 ؛ 8,18…","تقفز w فوق الحدّ الأدنى وتبتعد عنه: إنها تتباعد"],["0,01","0,29 بعد خمس خطوات","بالكاد تتقدّم w: إنها بطيئة جدًا"]],"legende":"الخطوة الأكبر لا تصل دائمًا أسرع.","notes":"افتحوا العرض التوضيحي للانحدار التدرّجي (درس «بعض خوارزميات التعلم الآلي») واطلبوا التوقّع قبل كل تجربة: η = 0,1، ثم 1,1، ثم 0,01. واجعلوا الطلبة يصوغون العبرة: إذا كانت الخطوة كبيرة جدًا، قفزت فوق الحدّ الأدنى؛ وإذا كانت صغيرة جدًا، صار التعلّم بطيئًا للغاية. ويضيف حلّ التمرين 2 ب حالة حدّية: مع η = 1، تتذبذب w بلا نهاية بين 0 و6."},{"type":"question","titre":"التحقق من الإشارة","question":"إذا كان الميل سالبًا، فماذا يحدث لـ w في الخطوة التالية؟","choix":["تتزايد","تتناقص","لا تتغيّر"],"reponse":"تتزايد","explication":"في w ← w − η · الميل، طرحُ عدد سالب يعني إضافته. وفي التمرين 2 ب، يساوي الميل −6، فتنتقل w من 0 إلى 0,6.","notes":"تصويت برفع الأيدي قبل الكشف. هذا هو سؤال بطاقة الخروج الذي يقترحه الدليل لهذا المفهوم؛ وإذا أخطأ كثيرون، فعودوا إلى السطر الأول من جدول التصحيح."},{"type":"tableau","titre":"الحصيلة · 10 دقائق: ثلاث خوارزميات","entetes":["الخوارزمية","خاضعة للإشراف أم لا؟","ما تُنتجه"],"lignes":[["خوارزمية k-المتوسطات","غير خاضعة للإشراف","مجموعات يؤوّلها الباحث ويسمّيها"],["الانحدار الخطي","خاضعة للإشراف","عدد يتنبّأ به المستقيم ŷ = w · x + b"],["الانحدار التدرّجي","لا هذا ولا ذاك: إنها طريقة","قيم المعاملات التي تقلّص الخطأ"]],"notes":"ابنوا الجدول مع الطلبة قبل عرضه: يأتي طالب إلى السبورة لكل سطر. المنتظر بالنسبة إلى الانحدار التدرّجي: ليس نموذجًا، بل طريقة لإيجاد معاملات نموذج، بخطوات صغيرة. ويُستعمل أيضًا لتصحيح أوزان الشبكات العصبية، وهي من محاور الحصة التالية."},{"type":"points","titre":"أخطاء شائعة","points":["إيقاف خوارزمية k-المتوسطات بعد تكرار واحد، أو نسيان إعادة حساب المراكز","تمديد مستقيم الانحدار بعيدًا عن البيانات الملاحَظة","الخطأ في الإشارة في w ← w − η · الميل","الاعتقاد بأن الخطوة الأكبر تصل دائمًا أسرع"],"notes":"أعيدوا قراءتها مع الطلبة: فقد صودف كلٌّ منها أثناء الحصة (التكرار 1 في التمرين 2 د، وx = 6 في التمرين 2 أ، والميل −6 وη = 1,1 في التمرين 2 ب)."},{"type":"fin","titre":"العمل الشخصي","points":["إتمام التمارين 2 أ و2 ب و2 د، ثم إنجاز التمرين 2 ج (k أقرب الجيران)","الموضوع 2 من المشروع المصغَّر: قراءة `kmeans_enquete.py` وطريقة المرفق"],"texte":"الحصة التالية: المحوِّلات (Transformers) والذكاء الاصطناعي التوليدي. وإلى ذلك الحين، تصفّحوا درس «التعلم العميق».","notes":"ذكّروا بتعليمة الأعمال الموجَّهة: البحث في كل تمرين عشرين دقيقة على الأقل قبل فتح الحل. وبالنسبة إلى الموضوع 2: تعتمد طريقة المرفق قيمة k التي لا تكاد العطالة تنخفض بعدها (k = 3 في مثال الدرس)."}]},{"id":"seance-8","numero":8,"titre":"المحوِّلات (Transformers) والذكاء الاصطناعي التوليدي","resume":"شرح الرمز (token) والتضمين والانتباه، ووصف توليد النص بوصفه تنبّؤًا متكرّرًا بالرمز التالي، والتحقّق من مرجع أنتجه وكيل محادثة.","duree":"ساعة ونصف","lien":"cours.html#c3-deep","fiche":"enseignant.html#guide-seance-8","diapos":[{"type":"titre","surtitre":"الفصل 3 · الحصة 8","titre":"المحوِّلات (Transformers) والذكاء الاصطناعي التوليدي","sousTitre":"كيف تكتب الآلة، ولماذا ينبغي التحقّق مما تكتبه","notes":"سير الحصة: تخمين الكلمة التالية (15 دقيقة)، والرموز والتضمينات والانتباه (20)، وعرض توضيحي (20)، واختبار المراجع (15)، والأخلاقيات (15)، والحصيلة (5). في عشية الحصة: ثبّتوا `transformers` و`torch` ونزّلوا النماذج (أو حضّروا Colab)، والتقطوا صورًا لشاشة المخرجات احتياطًا، واطلبوا من وكيل محادثة خمسة مراجع حول موضوع محدَّد. المكتسبات القبلية: الحصة 7، والاطلاع على درس «التعلم العميق»."},{"type":"points","titre":"أهداف الحصة","points":["شرح **الرمز** (token) و**التضمين** و**الانتباه**","وصف التوليد بوصفه **تنبّؤًا متكرّرًا بالرمز التالي**","**التحقّق** من مرجع أنتجه وكيل محادثة"],"notes":"أعلنوا خيط الحصة: يؤدي الطلبة أولًا دور نموذج لغوي، ثم نفتح العلبة، ونشغّل نماذج حقيقية، ثم نضعها على المحكّ."},{"type":"section","numero":1,"titre":"تخمين الكلمة التالية","sousTitre":"15 دقيقة، دون حاسوب","notes":"لا نظرية الآن: سيفعل الطلبة بأنفسهم ما يفعله النموذج التوليدي."},{"type":"question","titre":"أكملوا بصوت مرتفع","question":"«Il pleure dans mon…»","reponse":"الكلمة هي «cœur»: فيرلين، *Romances sans paroles* (1874).","explication":"يقدّم الجميع الكلمة نفسها: ففي هذا السياق، ثمة تتمّة واحدة محتملة جدًا.","notes":"اطلبوا إجابة جماعية. المنتظر: «cœur»، بالإجماع. إنها القصيدة التي عُدّت كلماتها بلغة Python في الأعمال الموجَّهة للفصل 2 (التمرين 3). سؤال يُطرح: كيف تعرفون ذلك؟ لأنكم سبق أن قرأتم هذه التتمّة. والنموذج اللغوي يقدّر كذلك احتمال متتالية من الكلمات، انطلاقًا من عدد كبير جدًا من النصوص."},{"type":"activite","titre":"«فتحت الطالبة الكتاب و…»","duree":7,"consignes":["يكتب كل طالب سرًّا الكلمة التالية، ثم يقرؤها بصوت مرتفع.","على السبورة: كل اقتراح وعدد الطلبة الذين قدّموه.","هذا الجدول **توزيع احتمالي** للكلمة التالية."],"materiel":"نصف ورقة لكل طالب؛ السبورة","notes":"دوّنوا كل اقتراح مع عدده. هذه المرة، تتباين الإجابات: فعدة تتمّات معقولة. واجعلوا الطلبة يقولون إن الاقتراح الأكثر تواترًا ليس الوحيد الممكن. اتركوا الجدول ظاهرًا من أجل الشريحة التالية."},{"type":"deux","titre":"اختيار الكلمة التالية: درجة الحرارة","colonnes":[{"titre":"درجة حرارة منخفضة","points":["أخذ الاقتراح الأكثر تواترًا دائمًا","نص متوقَّع","مع T < 1: تتعمّق الفروق بين الاحتمالات"]},{"titre":"درجة حرارة مرتفعة","points":["السحب بالقرعة من بين الاقتراحات","نص مفاجئ، ثم مفكَّك","مع T > 1: تتسطّح الفروق"]}],"notes":"أجروا السحبين بجدول القسم: مرة بأخذ الكلمة الأكثر تواترًا، ومرة بالقرعة (أوراق تُسحب من علبة، مثلًا). والنموذج يفعل ذلك بالضبط، رمزًا بعد رمز. أما صيغة الدرس، p(tokenᵢ) = exp(zᵢ / T) / Σⱼ exp(zⱼ / T)، فلا تُطلب من الطلبة."},{"type":"section","numero":2,"titre":"الرموز، والتضمينات، والانتباه","sousTitre":"20 دقيقة","notes":"اتّبعوا درس «التعلم العميق»، جزء «توليد النصوص بالمحوِّلات (Transformers)». ضعوا الأمر في سياقه: في 2017، اقترح المقال «Attention Is All You Need» (Ashish Vaswani وشركاؤه في التأليف، Google) المحوِّل (Transformer)، الذي يعالج كل كلمات المقطع في آنٍ واحد، ويحسب العلاقات بينها بواسطة آلية انتباه."},{"type":"definition","terme":"الرمز","traduction":"token (jeton)","definition":"وحدة النص التي يعالجها النموذج: كلمة، أو جزء من كلمة، أو علامة ترقيم. والكلمة النادرة تُقسَّم إلى عدة أجزاء.","exemple":"يضمّ معجم GPT-2 ما يزيد قليلًا على 50 000 رمز.","notes":"ألحّوا على أن النموذج لا يرى حروفًا ولا أفكارًا، بل متتالية من الرموز. وهو يتنبّأ دائمًا بالرمز التالي، لا بجملة كاملة ولا بإجابة جاهزة."},{"type":"definition","terme":"التضمين","traduction":"plongement","definition":"يصبح كل رمز متّجهًا من عدة مئات من الأعداد. والكلمات المستعملة في سياقات متشابهة تحصل على متّجهات متقاربة.","exemple":"الفرضية التوزيعية، كما لخّصها J. R. Firth سنة 1957: «*You shall know a word by the company it keeps*».","notes":"ترجموا الاستشهاد: نعرف الكلمة من رفقتها. واربطوا ذلك بالقراءة الأدبية: فمعنى الكلمة يُبنى أيضًا في سياقاتها. المتّجه لا يفهم شيئًا؛ إنه يلخّص الجوار الذي ترد فيه الكلمة."},{"type":"question","titre":"الانتباه","question":"«سلّمت الطالبة البحث إلى الأستاذ لأنها أنهته.» إلى أي كلمة ينبغي أن ينظر الرمز «ها» في «لأنها» أساسًا؟","choix":["«البحث»","«الأستاذ»","«الطالبة»"],"reponse":"«الطالبة»","explication":"**الانتباه**: يحسب كل رمز إلى أي حدّ عليه أن «ينظر» إلى كل رمز من الرموز الأخرى، مهما كانت المسافة بينهما. هذا هو قلب المحوِّل (Transformer).","notes":"اجعلوا الطلبة يصوّتون، ثم اسألوا كيف نعرف ذلك: تأنيث الضمير، ومعنى الجملة. أما النموذج فيتعلّم هذه الروابط من الأمثلة. وصيغة Attention(Q, K, V) = softmax(Q · Kᵀ / √d) · V موجودة في الدرس: لا داعي لتفصيلها. وتتيح هذه الآلية أيضًا معالجة كل الكلمات بالتوازي، في حين كانت الشبكة التكرارية (RNN) تقرأ كلمةً بعد كلمة."},{"type":"deux","titre":"عائلتان من المحوِّلات","colonnes":[{"titre":"المرمِّزات: BERT (Google، 2018)","points":["تقرأ الجملة في الاتجاهين","تُستعمل **للفهم**: التصنيف، وتحليل المشاعر، والكيانات المسمّاة","للفرنسية: CamemBERT؛ وللعربية: AraBERT"]},{"titre":"فاكّات الترميز: GPT (OpenAI، منذ 2018)","points":["تقرأ من اليسار إلى اليمين، أي من بداية النص إلى نهايته","تتنبّأ بالرمز التالي","تُستعمل **لتوليد** النصوص"]}],"notes":"خطأ شائع: الخلط بين BERT، الذي يفهم ويصنّف، وGPT، الذي يولّد. اربطوا ذلك بالمشروع المصغَّر: فتحليل المشاعر (الموضوع 1) والكيانات المسمّاة في خطاب سياسي (الموضوع 3) من اختصاص المرمِّزات."},{"type":"etapes","titre":"التوليد تكرارٌ في حلقة","etapes":[{"titre":"الحساب","texte":"يعطي النموذج احتمالًا لكل رمز من المعجم."},{"titre":"السحب","texte":"نسحب رمزًا بالقرعة وفق هذه الاحتمالات، التي تضبطها درجة الحرارة."},{"titre":"الإضافة","texte":"يُضاف الرمز المسحوب إلى نهاية النص."},{"titre":"إعادة الكرّة","texte":"يصبح النص المطوَّل نقطة انطلاق جديدة."}],"progressif":true,"notes":"هذا هو الهدف المحوري للحصة. اطلبوا من أحد الطلبة إعادة الصياغة انطلاقًا من لعبة البداية: فقد أنجز القسم هذه المراحل الأربع مع «فتحت الطالبة الكتاب و…». النتيجة التي ينبغي أن يصوغوها: النموذج لا يبحث عن معلومة، بل يواصل نصًا بطريقة معقولة."},{"type":"section","numero":3,"titre":"الاستعمال، والتحقّق، والتصريح","sousTitre":"عرض توضيحي (20 دقيقة) · المراجع (15 دقيقة) · الأخلاقيات (15 دقيقة)","notes":"نشغّل الآن نماذج حقيقية، ثم نضعها على المحكّ. وإذا تعذّر الاتصال أو التثبيت، فاعرضوا لقطات الشاشة التي حضّرتموها عشية الحصة."},{"type":"code","titre":"عرض توضيحي: التوليد بنموذج GPT-2","code":"from transformers import pipeline, set_seed\n\n# GPT-2 (2019) : petit modèle génératif, textes anglais\ngenerateur = pipeline(\"text-generation\", model=\"gpt2\")\nset_seed(42)  # tirage reproductible sur une même installation\n\ndebut = \"The old librarian opened the forbidden book and\"\nsorties = generateur(debut, max_new_tokens=40, do_sample=True,\n                     temperature=0.3, num_return_sequences=2)\nfor s in sorties:\n    print(s[\"generated_text\"], end=\"\\n\\n\")","legende":"البرنامج `generation_texte.py` (الدرس)، مع `temperature=0.3`، ثم `1.5`. تتوقف التتمّة على البذرة، ودرجة الحرارة، والإصدارات المثبَّتة: لا مُخرَج ثابت.","notes":"اطلبوا التوقّع قبل التنفيذ: مع 0,3، نص متوقَّع إلى حدّ ما؛ ومع 1,5، نص مفاجئ، ثم مفكَّك. اقرؤوا المخرجات بصوت مرتفع، واطلبوا من الطلبة رصد الجمل المعقولة لكنها عبثية أو خاطئة. إن GPT-2 نموذج إنجليزي نُشر سنة 2019؛ فبالنسبة إلى الفرنسية أو العربية، يجب اختيار نموذج آخر من منصّة Hub التابعة لـ Hugging Face. نحو 10 دقائق."},{"type":"code","titre":"عرض توضيحي: نموذج إنجليزي يصنّف","code":"from transformers import pipeline\n\n# Modèle anglais affiné sur des critiques de films (SST-2)\nmodele = (\"distilbert/distilbert-base-uncased-\"\n          \"finetuned-sst-2-english\")\nanalyseur = pipeline(\"sentiment-analysis\", model=modele)\navis = [\n    \"I loved this novel, the characters are unforgettable.\",\n    \"The ending was a real disappointment.\",\n]\nfor texte, resultat in zip(avis, analyseur(avis)):\n    print(resultat[\"label\"], \"|\", texte)","sortie":"POSITIVE | I loved this novel, the characters are unforgettable.\nNEGATIVE | The ending was a real disappointment.","legende":"البرنامج `sentiment_transformers.py` (الدرس). أضيفوا بعد ذلك جملة بالفرنسية إلى القائمة `avis`: بماذا يجيب هذا النموذج المدرَّب على الإنجليزية؟","notes":"نفّذوا البرنامج أولًا كما هو: يُصنَّف الرأيان الإنجليزيان تصنيفًا صحيحًا. ثم أضيفوا جملة بالفرنسية من اختياركم، وأعيدوا التشغيل أمام الطلبة دون الإعلان عن النتيجة. وأيًّا كانت النتيجة، اطرحوا السؤال: هل يستطيع نموذج أُعيد ضبطه على نقد أفلام بالإنجليزية أن يحكم على نص فرنسي؟ اربطوا ذلك بالموضوعين 1 (المشاعر) و3 (الخطابات السياسية) من المشروع المصغَّر. نحو 10 دقائق."},{"type":"activite","titre":"اختبار المراجع","duree":15,"consignes":["إليكم خمسة مراجع اقترحها وكيل محادثة حول موضوع محدَّد.","تأخذ كل مجموعة مرجعًا واحدًا وتبحث عنه في فهرس مكتبة.","هل هو موجود؟ وهل المؤلف والعنوان والناشر والسنة صحيحة؟","تعلن كل مجموعة حكمها في جملة واحدة."],"materiel":"المراجع الخمسة، المطلوبة عشية الحصة، مطبوعة أو معروضة؛ وإمكانية الوصول إلى فهرس مكتبة","notes":"اختاروا موضوعًا محدَّدًا من تخصّصكم. يمكنكم التحقّق من المراجع قبل الدرس، لكن لا تُعلنوا النتيجة. فإذا كان بعضها غير موجود، فبيّنوا أن الأداة اختلقتها بثقة تامة؛ وإذا كانت كلها موجودة، فالدرس يتعلّق بالتحقّق نفسه. خطأ شائع ينبغي تسميته: الوثوق بمرجع لأنه مقدَّم بشكل جيد."},{"type":"definition","terme":"الهلوسة","traduction":"hallucination","definition":"يُنتج النموذج التوليدي التتمّة الأكثر معقولية، لا الأكثر صدقًا: فقد يختلق بثقة تامة استشهادًا، أو تاريخًا، أو مرجعًا كاملًا لا وجود له.","exemple":"قاعدة للمذكرة: لا تستشهدوا أبدًا بمصدر لم تعثروا عليه وتقرؤوه بأنفسكم.","notes":"استخلصوا العبرة من الاختبار: المرجع غير الموجود في مذكرة خطأ علمي، أيًّا كان مصدره. ويُتحقَّق من كل استشهاد في الطبعة الأصلية."},{"type":"activite","titre":"الأخلاقيات: ثلاث قواعد للقسم","duree":15,"consignes":["التصريح باستعمال الذكاء الاصطناعي في المذكرة: ما الذي يجب ذكره؟","إيداع نصوص على الإنترنت: ما النصوص التي لا يجوز إيداعها أبدًا؟","الدارجة، والأمازيغية: ماذا نفعل حين تكون لغةٌ أقلّ حظًّا في المعالجة؟","حرّروا معًا ثلاث قواعد، في جملة واحدة لكل قاعدة."],"materiel":"درسا «الآفاق: الفرص والحدود والأخلاقيات» و«التعلّم مع مساعد ذكاء اصطناعي، دون غش»","notes":"المنتظر، بحسب الدرسين. التصريح: اسم الأداة، وإصدارها، والتاريخ، والاستعمال الدقيق، والتعليمات المصوغة؛ وتقديم نص مولَّد على أنه من إنتاج الطالب يُعدّ سرقة علمية. لا يجوز أبدًا إيداع بيانات شخصية ولا نصوص غير منشورة أو محمية في خدمة تعيد استعمال المحتويات. واللغات القليلة الحضور على الويب، كالدارجة أو الأمازيغية، أقلّ حظًّا في المعالجة من الإنجليزية: يجب التحقّق من النتائج على عيّنة. اكتبوا القواعد الثلاث على السبورة."},{"type":"points","titre":"أخطاء شائعة","points":["الاعتقاد بأن النموذج يعرف أو يبحث: إنه يواصل نصًا بطريقة معقولة","الوثوق بمرجع لأنه مقدَّم بشكل جيد","الخلط بين BERT، الذي يفهم ويصنّف، وGPT، الذي يولّد"],"notes":"اطلبوا ربط كل خطأ بلحظة من الحصة: لعبة الكلمة التالية، واختبار المراجع، وعائلتا المحوِّلات."},{"type":"fin","titre":"الحصيلة · 5 دقائق","texte":"أكملوا على نصف ورقة: «توليد النص، بالنسبة إلى النموذج، هو…»","points":[{"texte":"**العمل الشخصي**","sous":["إعادة قراءة الإطار «الهلوسة والمصادر»، ثم كتابة قاعدة شخصية لاستعمال مساعد الذكاء الاصطناعي في خمسة أسطر","للمجموعة المعنية: تحضير المائدة المستديرة «الذكاء الاصطناعي مولِّدًا لإشكاليات جديدة»"]}],"notes":"اجمعوا الجمل المكتملة. المنتظر: التنبّؤ، رمزًا بعد رمز، بتتمّة معقولة؛ أي حساب احتمالات، وسحب رمز، وإضافته، وإعادة الكرّة. وافتتحوا الحصة التالية بالإجابات الأكثر تواترًا."}]},{"id":"mini-projet","titre":"إطلاق المشروع المصغَّر","resume":"اختيار موضوع للمشروع المصغَّر ضمن مجموعة، مع معرفة المنهجية، والبيانات الممكنة، والمُخرَجات، والجدول الزمني، والمناقشة الشفوية، والتقييم.","duree":"ثلاثة أسابيع","lien":"cours.html#mini-projet","diapos":[{"type":"titre","surtitre":"المشروع المصغَّر · عمل شخصي مؤطَّر","titre":"المشروع المصغَّر","sousTitre":"خمسة مواضيع، وست مجموعات، وثلاثة أسابيع لبحث صغير متكامل","notes":"يُعرض في نهاية الفصل 2: وهو الموعد الذي ينصّ فيه البرنامج الرسمي على توزيع المشروع المصغَّر، لثلاثة أسابيع من العمل الشخصي المؤطَّر. قبل الحصة، حدّدوا قاعدة عدد المواضيع، وتاريخ التسليم، وطريقة الإرسال، ومدة العرض الشفهي، وتحقّقوا لكل موضوع من توفّر مصدر بيانات يمكن الوصول إليه. وكل ما يوصف بأنه «استرشادي» مأخوذ من الدليل ويبقى قابلًا للتكييف."},{"type":"points","titre":"بحث صغير متكامل","points":["طرح سؤال بحث","جمع البيانات","معالجتها بلغة Python","تأويل النتائج بالنظرة النقدية لتخصّصكم","ثلاثة أعمال: **دفتر** (notebook)، و**تقرير**، و**عرض شفهي**"],"progressif":true,"notes":"قدّموا المشروع المصغَّر بوصفه بحثًا مصغَّرًا، لا تمرينًا في البرمجة. والمرحلة الأخيرة، أي التأويل، هي التي يتفوّق فيها طلبة الآداب: فالأداة تُنتج قرائن، وسؤال البحث هو الذي يمنحها معنى."},{"type":"deux","titre":"موضوع واحد أم ثلاثة؟ البرنامج يقول الأمرين","colonnes":[{"titre":"تقديم المشروع المصغَّر","points":["«عالِج موضوعًا واحدًا تختاره من بين» المواضيع الخمسة"]},{"titre":"المنهجية البيداغوجية","points":["«مشروع مصغَّر (إنجاز 3 مواضيع على الأقل من بين المواضيع الخمسة المقترحة)»"]}],"notes":"يقدّم البرنامج الرسمي إشارتين مختلفتين: لا تتركوا الطلبة في حيرة. أعلنوا هنا القاعدة التي اعتمدتموها، بالتشاور مع رئيس قسمكم عند الحاجة، واكتبوها على السبورة والتزموا بها طوال السداسي. وإذا اعتمدتم ثلاثة مواضيع، فإن الدليل يقترح توزيعها من الأسبوع 4 إلى الأسبوع 9، بمعدل موضوع كل أسبوعين. وإذا كانت القاعدة موضوعًا واحدًا، يمكنكم السماح للمجموعات الأسرع بمعالجة موضوع ثانٍ."},{"type":"section","numero":1,"titre":"المواضيع الخمسة","sousTitre":"المناهج، والأدوات، والبيانات","notes":"لكل موضوع صفحته في الموقع: الهدف، وسؤال بحث ممكن، والبيانات، والمُخرَجات، والأدوات الواردة في البرنامج، وخطوات العمل مرحلةً مرحلة، وشيفرة أولية."},{"type":"tableau","titre":"خمسة مواضيع للاختيار","entetes":["الموضوع","المنهج","الأدوات الواردة في البرنامج"],"lignes":[["1. المشاعر في شبكات التواصل الاجتماعي","قطبية النصوص: إيجابية أو سلبية أو محايدة","TextBlob وVADER وpandas وmatplotlib"],["2. عنقدة الاستبيانات","خوارزمية k-المتوسطات: مجموعات تتكوّن دون أوسام","pandas وscikit-learn وseaborn"],["3. الخطابات السياسية","الكيانات المسمّاة والموضوعات (LDA)","spaCy وBERT وgensim وWordCloud"],["4. النمذجة التنبؤية","الانحدار اللوجستي: تقدير نتيجة (نعم أو لا)","scikit-learn وpandas وseaborn"],["5. تحليل الشبكات","مخطط العلاقات، ومقاييس المركزية","NetworkX وGephi وpandas"]],"legende":"تفاصيل كل موضوع في صفحة «المشروع المصغَّر» على الموقع.","notes":"طمئنوا الطلبة: ستُدرَس المناهج في الفصل 3، أثناء المشروع المصغَّر، وكل صفحة موضوع توفّر شيفرة أولية. يذكر البرنامج sklearn وscikit-learn: وهما المكتبة نفسها. وبالنسبة إلى الموضوع 1، يصعب استعمال Tweepy (فواجهة برمجة التطبيقات الخاصة بمنصة X مدفوعة منذ 2023)، ولا تفيد GeoPandas إلا إذا كانت النصوص مرتبطة بمكان."},{"type":"question","titre":"سؤال واحد، فأيّ موضوع؟","question":"«هل تُقرأ البنية المتشظّية لرواية *Nedjma* في شبكة شخصياتها؟» إلى أي موضوع ينتمي سؤال البحث هذا؟","choix":["الموضوع 1 · المشاعر","الموضوع 2 · العنقدة","الموضوع 3 · الخطابات السياسية","الموضوع 4 · التنبؤ","الموضوع 5 · الشبكات"],"reponse":"الموضوع 5 · الشبكات","explication":"الشخصيات هي العقد، وحضورها المشترك هو الروابط؛ ومقاييس المركزية تبيّن من يربط بين المجموعات ومن يبقى على الهامش.","notes":"اقرؤوا بعد ذلك الأسئلة الأخرى المقترحة في الموقع. الموضوع 1: كيف تلقّى مستخدمو الإنترنت اقتباس رواية للسينما أو للتلفزيون؟ الموضوع 2: هل توجد أنماط متمايزة من القرّاء بين طلبة الماستر؟ الموضوع 3: ما الموضوعات والأماكن الغالبة على خطابات المناقشة العامة في الأمم المتحدة؟ الموضوع 4: ما العوامل المرتبطة بمشاركة الطلبة في الأحداث الثقافية؟ يمكن لكل مجموعة أن تستلهم منها، لكنها تصوغ سؤالها الخاص."},{"type":"tableau","titre":"أين نجد البيانات","entetes":["الموضوع","البيانات الممكنة"],"lignes":[["1. المشاعر","مدوّنات Sentiment140 وAllociné وLABR؛ تعليقات عامة تُجمع يدويًا"],["2. العنقدة","استبيانكم المجهول الهوية؛ World Values Survey وArab Barometer"],["3. الخطابات","المواقع الرسمية، وvie-publique.fr، وUN General Debate Corpus"],["4. التنبؤ","استبيانكم (سؤال نعم/لا)؛ مجموعات البيانات العامة في UCI"],["5. الشبكات","جدول روابط يُرصد أثناء القراءة؛ شبكات الأمثلة في NetworkX"]],"legende":"لكل مجموعة بيانات: من أنتجها، وأين، ومتى، وكيف جُمعت.","notes":"يقتضي الاستبيان (الموضوعان 2 و4) موافقة المستجوَبين وإخفاء هويّاتهم، ويحتاج ملؤه إلى وقت: فيجب أن يُرسَل منذ الأسبوع الأول. ومع بضع عشرات من الإجابات فقط، تظل الاستنتاجات حذرة جدًا. وبالنسبة إلى الموضوع 5، فرواية *Nedjma* محمية بحقوق المؤلف: نتقاسم جداول الروابط، لا النص المرقمَن. وإذا بدا لكم مصدر غير مضمون، فحضّروا مجموعة بيانات صغيرة لتوفيرها."},{"type":"activite","titre":"توزيع المواضيع على المجموعات الست","duree":20,"consignes":["تعيد كل مجموعة قراءة المواضيع الخمسة في الموقع وتختار ثلاثة منها، مرتّبة حسب الأفضلية.","المعايير: أهمية السؤال، وتوفّر البيانات، وتجهيزات المجموعة.","يعلن المتحدث باسم المجموعة الاختيارات الثلاثة؛ ويحكم الأستاذ بينها على السبورة.","تدوّن كل مجموعة موضوعها وفكرة أولى عن سؤال البحث."],"materiel":"صفحة «المشروع المصغَّر» في الموقع (هاتف أو قاعة إعلام آلي)؛ شبكة الشريحة التالية","notes":"إجراء مقترح، لا قاعدة من البرنامج: كيّفوه. ست مجموعات لخمسة مواضيع: مع قاعدة الموضوع الواحد، ستأخذ مجموعتان الموضوع نفسه، ويمكنهما اختيار مدوّنات مختلفة ومقارنة نتائجهما في العرض الشفهي. ومع قاعدة المواضيع الثلاثة، تختار كل مجموعة ثلاثة، وتسهرون على التوازن. التجهيزات: يتطلّب الموضوعان 1 و3 مكتبات ثقيلة (transformers وtorch وspaCy) واتصالًا جيدًا؛ ويتطلّب الموضوع 5 تثبيت Gephi على حدة. ويمكن لمجموعة بلا حاسوب أن تعمل في Colab أو في قاعة الإعلام الآلي."},{"type":"tableau","titre":"توزيع المواضيع","entetes":["المجموعة","الموضوع (أو المواضيع)","فكرة أولى عن السؤال","البيانات المتوقَّعة"],"lignes":[["المجموعة 1","","",""],["المجموعة 2","","",""],["المجموعة 3","","",""],["المجموعة 4","","",""],["المجموعة 5","","",""],["المجموعة 6","","",""]],"legende":"شبكة تُنقل على السبورة أو تُطبع؛ ويصادق الأستاذ على كل سطر خلال الأسبوع الأول.","notes":"املؤوا الشبكة على السبورة أثناء التحكيم، ثم ضعوها في الفضاء الرقمي للقسم (Moodle أو مجموعة مراسلة): فتصبح المرجع المشترك. ويتيح تصدير العرض بصيغة PDF أيضًا طباعتها فارغة."},{"type":"points","titre":"العمل ضمن مجموعة","points":["أدوار متناوبة: كاتب، ومتحدث باسم المجموعة، وضابط للوقت","يمسك لوحة المفاتيح الأقلّ تمكّنًا، ويوجّهه الآخر، ويتبادلان الأدوار بانتظام","**سجلّ عمل** مؤرَّخ: ما جرّبناه، وما أخفق، وما قرّرناه ولماذا","يعرف كل عضو كيف يشرح أي خلية من الدفتر","يُعرض التقدّم على الأستاذ كل أسبوع"],"notes":"هذه النصائح مأخوذة من الدليل ومن صفحة «منهجية العمل». وفي العمل الجماعي، يقترح الدليل تنقيط الشيفرة والتقرير جماعيًا، والمناقشة الشفوية فرديًا: فيجيب كل عضو عن سؤال يخصّ جزءًا لم يعرضه هو. وإذا اعتمدتم هذا المبدأ، فأعلنوه منذ اليوم: فهو يمنع أن يكتب طالب واحد الشيفرة كلها."},{"type":"section","numero":2,"titre":"المنهجية والجدول الزمني","sousTitre":"ثلاثة أسابيع، وست مراحل","notes":"المنهجية واحدة في كل المواضيع؛ ثم تفصّلها كل صفحة موضوع خطوةً خطوة."},{"type":"etapes","titre":"ست مراحل في ثلاثة أسابيع","etapes":[{"titre":"الأسبوع 1 · الاختيار والتأطير","texte":"سؤال بحث دقيق، وفرضية أو فرضيتان، يصادق عليها الأستاذ."},{"titre":"الأسبوع 1 · جمع البيانات","texte":"الجمع، وتحرير بطاقة مصدر، وإخفاء الهويات، والتحميل في جدول pandas."},{"titre":"الأسبوع 2 · الاستكشاف والتنظيف","texte":"العدّ، والفرز، وكشف التكرارات والقيم الناقصة؛ وتدوين كل قرار."},{"titre":"الأسبوع 2 · تطبيق المنهج","texte":"أداة الموضوع أو خوارزميته، مع التحقّق منها على عيّنة صغيرة يقرؤها الطالب بنفسه."},{"titre":"الأسبوع 3 · التأويل والمناقشة","texte":"العودة إلى النصوص أو البيانات؛ وتحديد التحيّزات والحدود."},{"titre":"الأسبوع 3 · التحرير والعرض","texte":"تحرير التقرير، وإعادة تشغيل الدفتر كاملًا، وتحضير العرض الشفهي."}],"progressif":true,"notes":"الأسابيع 1 و2 و3 هنا هي الأسابيع الثلاثة للمشروع المصغَّر، لا أسابيع السداسي. نصيحة من صفحة «منهجية العمل»: البدء صغيرًا؛ فمدوّنة من خمسين نصًا تعمل خير من عشرة آلاف نص لا تعمل. والمرحلة الأكثر نسيانًا هي التحقّق على عيّنة تُقرأ يدويًا: ألحّوا عليها."},{"type":"points","titre":"قواعد مشتركة بين جميع المواضيع","points":["**المصادر**: من أنتج البيانات، وأين، ومتى، وكيف جُمعت","**الحياة الخاصة**: حذف الأسماء والأسماء المستعارة والمعرّفات؛ وموافقة المستجوَبين","**الحقوق**: شروط الاستخدام وحقوق المؤلف؛ التحليل ليس إعادة نشر","**قابلية إعادة الإنتاج**: يستطيع شخص آخر إعادة تشغيل الدفتر والحصول على النتائج نفسها","**الشفافية**: يُصرَّح بكل استعمال لمساعد ذكاء اصطناعي، ويُتحقَّق من كل ما ينتجه"],"notes":"ترد هذه القواعد الخمس في صفحة المشروع المصغَّر، وهي تسري على جميع المواضيع. الحياة الخاصة: في الجزائر، يؤطّر القانون رقم 18-07 المؤرخ في 10 يونيو 2018 معالجة المعطيات ذات الطابع الشخصي. الحقوق: يجوز تحليل رواية حديثة، لكن لا يجوز إعادة نشرها على الإنترنت. الشفافية: يقترح الدليل أن يُختم كل تقرير بتصريح باستعمال أدوات الذكاء الاصطناعي (الأداة، والتاريخ، والاستعمال، والتعليمات، والتحقّق)، حتى لو كانت الإجابة «لا شيء»."},{"type":"chronologie","titre":"جدول زمني استرشادي (يُكيَّف)","evenements":[{"date":"الأسبوع 3","texte":"نهاية الفصل 2: توزيع المشروع المصغَّر"},{"date":"الأسبوع 4","texte":"التأطير وجمع البيانات؛ المصادقة على أسئلة البحث"},{"date":"الأسبوع 5","texte":"الاستكشاف والتنظيف وتطبيق المنهج؛ نقطة مرحلية"},{"date":"الأسبوع 6","texte":"التأويل والتحرير؛ تسليم الدفتر والتقرير"},{"date":"الأسبوع 7","texte":"ملاحظات فردية حول المشاريع المصغَّرة"},{"date":"الأسبوع 8","texte":"التحضير للمناقشات"},{"date":"الأسبوع 10","texte":"المناقشات"}],"notes":"هذا الجدول هو الذي يقترحه الدليل على ثلاثة عشر أسبوعًا، في حالة قاعدة الموضوع الواحد. ووحدهما التوزيع في نهاية الفصل 2 ومدة الأسابيع الثلاثة مأخوذان من البرنامج الرسمي. استبدلوا أرقام الأسابيع بتواريخ رزنامة كليتكم، وأعلنوا تاريخ التسليم، وطريقة الإرسال، ومدة العرض الشفهي. ومع ثلاثة مواضيع، وزّعوها من الأسبوع 4 إلى الأسبوع 9."},{"type":"section","numero":3,"titre":"المُخرَجات، والعرض الشفهي، والتقييم","sousTitre":"ما تسلّمونه، وكيف سيُقيَّم","notes":"وزّعوا شبكة التقييم منذ اليوم، مع الموضوع: فيعرف الطلبة بذلك ما الذي يُحتسب."},{"type":"tableau","titre":"ما تسلّمونه","entetes":["المُخرَج","المنتظر"],"lignes":[["دفتر Jupyter","يُنفَّذ دون خطأ من أوله إلى آخره بعد إعادة تشغيل النواة"],["البيانات","مرفقة بالدفتر، أو طريقة الحصول عليها مشروحة بدقة"],["التقرير (من 4 إلى 6 صفحات)","السؤال، والبيانات، والمنهج، والنتائج، والتأويل، والحدود"],["الرسوم البيانية","مرقّمة ومعنونة ومعلَّق عليها في متن التقرير"],["العرض الشفهي","سؤالكم، ونتيجتكم الرئيسية، وحدٌّ واحد من حدود مقاربتكم"]],"legende":"تاريخ التسليم، ومدة العرض الشفهي، وطريقة الإرسال: يحدّدها الأستاذ.","notes":"دفتر Jupyter وثيقة تمزج بين خلايا الشيفرة والنتائج والنص التوضيحي. الخطة المقترحة للتقرير: سؤال البحث، والبيانات، والمنهج، والنتائج، والتأويل، والحدود والمسائل الأخلاقية، والمراجع. ويضيف كل موضوع مُخرَجاته الخاصة المفصَّلة في صفحته: عيّنة موسومة يدويًا (الموضوع 1)، وقاموس المتغيّرات (الموضوع 2)، وجدول الكيانات (الموضوع 3)، والمقارنة مع نموذج ساذج (الموضوع 4)، وملف GEXF (الموضوع 5)."},{"type":"points","titre":"المناقشة الشفوية","points":["اعرضوا سؤالكم، ونتيجتكم الرئيسية، وحدًّا واحدًا من حدود مقاربتكم","«اعرضوا الخلية التي تنظّف البيانات واشرحوا كل سطر منها.»","«انتقلوا من k = 3 إلى k = 4 أمامي: ما الذي يتغيّر؟»","«اذكروا ثلاث رسائل أخطأ نموذجكم في تصنيفها واشرحوا كل خطأ.»"],"progressif":true,"notes":"الأسطر الثلاثة الأخيرة أمثلة على أسئلة يقترحها الدليل للعرض الشفهي: لا يستطيع الإجابة عنها إلا صاحب العمل، مما يجعل العرض الشفهي أكثر إقناعًا من أي كاشف للنصوص المولَّدة. نبّهوا الطلبة منذ اليوم: فهذا أفضل حافز لفهم كل سطر من دفترهم. ومدة العرض الشفهي تحدّدونها أنتم."},{"type":"tableau","titre":"شبكة التقييم (نقاط استرشادية على 20)","entetes":["المعيار","النقاط","مستوى «جيد»"],"lignes":[["سؤال البحث","3","دقيق، مرتبط بالعلوم الإنسانية والاجتماعية أو بالأدب، ممكن في 3 أسابيع"],["البيانات والأخلاقيات","3","المصدر والتاريخ وطريقة الجمع مذكورة؛ إخفاء الهوية والتنظيف موصوفان"],["المنهج والشيفرة","4","يُنفَّذ من أوله إلى آخره؛ شيفرة مشروحة بتعليقات؛ المعاملات مذكورة"],["النتائج والتأويل","4","رسوم بيانية معنونة ومعلَّق عليها؛ عودة إلى النصوص أو البيانات"],["التقرير","3","اتباع الخطة المقترحة، من 4 إلى 6 صفحات، ومراجع كاملة"],["المناقشة الشفوية","3","يلتزم بالوقت، ويشرح خلية من الشيفرة وحدًّا من الحدود"]],"legende":"سلّم تنقيط استرشادي من الدليل؛ ويخضع التنقيط الرسمي للنصوص السارية المفعول. وقبل التسليم، راجعوا عملكم بشبكة التقييم الذاتي في الموقع.","notes":"لا يذكر البرنامج سوى «التقييم (مطابق للنصوص السارية المفعول)»: لا تعلنوا أي نسبة مئوية لم تحدّدها كليتكم، وردّوا هذه النقاط إلى الحصة التي تمنحها النصوص للمشروع المصغَّر. أما المستويات الأخرى (غير كافٍ، ومقبول، وجيد جدًا) ففي الدليل، ضمن باب «تقييم الطلبة»."},{"type":"deux","titre":"مزالق ينبغي تجنّبها","colonnes":[{"titre":"ما يُتجنَّب","points":["مجرد موضوع عام: «المشاعر على Facebook»","بيانات بلا مصدر، أو لم تُخفَ فيها الهوية","دفتر لا يُنفَّذ من أوله إلى آخره","أرقام ورسوم بيانية بلا تعليق"]},{"titre":"ما يُفعَل","points":["سؤال دقيق، مع فرضية للمناقشة","بطاقة مصدر؛ وبيانات مجهولة الهوية","إعادة تشغيل الدفتر كله قبل تسليمه","العودة إلى النصوص لتأويل الأرقام"]}],"notes":"يستعيد عمود «ما يُتجنَّب» مستوى «غير كافٍ» في الشبكة، وعمود «ما يُفعَل» مستويي «جيد» و«جيد جدًا». اسألوا كل مجموعة عن المزلق الذي يتهدّدها أكثر من غيره، بالنظر إلى موضوعها."},{"type":"fin","titre":"للأسبوع القادم","points":["قراءة صفحة موضوعكم كاملة","صياغة سؤال بحث وفرضية أو فرضيتين","تحديد مصدر بيانات يمكن الوصول إليه، والبدء في بطاقة المصدر","فتح سجلّ العمل"],"texte":"يصادق الأستاذ على تأطير كل مجموعة خلال الأسبوع الأول.","notes":"حدّدوا موعد المصادقة على التأطير (حصة أعمال تطبيقية أو موعد خاص)، وذكّروا بالقناة الوحيدة للقسم لطرح الأسئلة. وإذا حضّرت مجموعة استبيانًا، فاطلبوا الاطلاع عليه قبل نشره: يجب أن يتضمّن الموافقة وإخفاء الهوية."}]}];
